window.MIT_COURSE_PARTS=window.MIT_COURSE_PARTS||[];window.MIT_COURSE_PARTS.push([{"code":"15.095","title":"Machine Learning Under a Modern Optimization Lens","level":"G","description":"Develops algorithms for central problems in machine learning from a modern optimization perspective. Topics include sparse, convex, robust and median regression; an algorithmic framework for regression; optimal classification and regression trees, and their relationship with neural networks; how to transform predictive algorithms to prescriptive algorithms; optimal prescriptive trees; and robust classification.  Also covers design of experiments, missing data imputations, mixture of Gaussian models, exact bootstrap, and sparse matrix estimation, including principal component analysis, factor analysis, inverse co-variance matrix estimation, and matrix completion.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"16:00","end":"17:30","room":"E51-345"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E51-345"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.095"},{"code":"15.128","title":"Revolutionary Ventures: How to Invent and Deploy Transformative Technologies","level":"G","description":"Seminar on envisioning and building ideas and organizations to accelerate engineering revolutions. Focuses on emerging technology domains, such as neurotechnology, imaging, cryotechnology, gerontechnology, and bio-and-nano fabrication. Draws on historical examples as well as live case studies of existing or emerging organizations, including labs, institutes, startups, and companies. Goals range from accelerating basic science to developing transformative products or therapeutics. Each class is devoted to a specific area, often with invited speakers, exploring issues from the deeply technical through the strategic. Individually or in small groups, students prototype new ventures aimed at inventing and deploying revolutionary technologies.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"16:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.128"},{"code":"15.136","title":"Principles and Practice of Drug Development","level":"G","description":"Description and critical assessment of the major issues and stages of developing a pharmaceutical or biopharmaceutical. Drug discovery, preclinical development, clinical investigation, manufacturing and regulatory issues considered for small and large molecules. Economic and financial considerations of the drug development process. Multidisciplinary perspective from faculty in clinical; life; and management sciences; as well as industry guests.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"18:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.136"},{"code":"15.223","title":"Global Markets, National Policies and the Competitive Advantages of Firms","level":"G","description":"Examines opportunities and risks firms face in today's global market. Provides conceptual tools for analyzing how governments and social institutions influence economic competition among firms embedded in different national settings. Public policies and institutions that shape competitive outcomes are examined through cases and analytical readings on different companies and industries operating in both developed and emerging markets.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E51-345"},{"days":["T","R"],"start":"13:00","end":"14:30","room":"E62-262"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.223"},{"code":"15.269","title":"Leadership Stories: Literature, Ethics, and Authority","level":"G","description":"Explores how we use story to articulate ethical norms. The syllabus consists of short fiction, novels, plays, feature films and some non-fiction. Major topics include leadership and authority, professionalism, the nature of ethical standards, social enterprise, and questions of gender, cultural and individual identity, and work/life balance. Materials vary from year to year, but past readings have included work by Chimamanda Ngozi Adichie, Seamus Heaney, Aravind Adiga, Ursula LeGuin, Hao Jingfang, Mohsin Hamid, and others; films have included The Lives of Others, Daughters of the Dust, Hotel Rwanda, Hamilton, and others. Draws on various professions and national cultures, and is run as a series of moderated discussions, with students centrally engaged in the teaching process.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-057"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.269"},{"code":"15.273","title":"Strategic Communication for Finance Professionals","level":"G","description":"Designed to help students develop and polish a range of communication skills necessary for success as a finance professional. Emphasis on presentation, team, and writing skills important to the finance professions. Restricted to MIT Sloan Master of Finance students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-057"},{"days":["T","R"],"start":"10:00","end":"11:30","room":"E51-151"},{"days":["M","W"],"start":"13:00","end":"14:30","room":"E62-221"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.273"},{"code":"15.275","title":"Entertainment, Media, and Sports Lab (EMS Lab)","level":"G","description":"Explores the market structure and dynamics of the entertainment, media, and sports industries. An action learning project gives students an opportunity to work with a host organization and contribute to solving real problems in these industries. Curriculum is designed to expose students to both the creative and commercial sides of entertainment, media, and sports. Provides instruction in the creative process, including content development and production, and presents strategies to distribute, promote, and measure content. Assignments include individual papers and the term-long action learning project.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"16:00","end":"19:00","room":"E62-250"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.275"},{"code":"15.276","title":"Communicating with Data","level":"U","description":"Equips students with the strategies, tactics, and tools to use quantitative information to inform and persuade others. Emphasizes effective communication skills as the foundation of successful careers. Develops the skills to communicate quantitative information in a business context to drive people and organizations toward better decisions. Focuses heavily on the cycle of practicing, reflecting, and revising. Students receive extensive, personalized feedback from teaching team and classmates. Limited to 25.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E62-221"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E62-221"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.276"},{"code":"15.280","title":"Communication for Leaders","level":"G","description":"Students develop and polish communication strategies and methods through discussion, examples, and practice. Emphasizes writing and speaking skills necessary for effective leaders. Includes several oral and written assignments which are integrated with other subjects, and with career development activities, when possible. Schedule and curriculum coordinated with Organizational Processes. Mandatory one hour recitation in small groups. Restricted to first-year Sloan graduate students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"14:30","room":"E62-223"},{"days":["T"],"start":"13:00","end":"14:30","room":"E51-145"},{"days":["T"],"start":"14:30","end":"16:00","room":"E51-325"},{"days":["T"],"start":"14:30","end":"16:00","room":"E62-250"},{"days":["T"],"start":"13:00","end":"14:30","room":"E51-325"},{"days":["T"],"start":"13:00","end":"14:30","room":"E51-335"},{"days":["T"],"start":"16:00","end":"17:30","room":"E62-250"},{"days":["T"],"start":"16:00","end":"17:30","room":"E51-325"},{"days":["T"],"start":"16:00","end":"17:30","room":"E51-335"},{"days":["T"],"start":"16:00","end":"17:30","room":"E62-223"},{"days":["T"],"start":"14:30","end":"16:00","room":"E62-223"},{"days":["T"],"start":"14:30","end":"16:00","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.280"},{"code":"15.284","title":"Strategic Leadership Communication","level":"G","description":"Introduces the essentials of how individuals and organizations develop and implement effective communication strategies, focusing on persuasion, audience analysis, communicator credibility, message construction, and delivery. Includes oral presentations and writing assignments with feedback to help students improve their communication effectiveness. Provides instruction to create communication strategies, develop and present clearly organized and powerful presentations, expand personal oral delivery and writing styles, and enhance presentations through effective visual aids. Restricted to Sloan Fellow MBAs.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"E62-221"},{"days":["M","W"],"start":"13:00","end":"14:30","room":"E62-221"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.284"},{"code":"15.288","title":"Tough Conversations","level":"G","description":"Equips managers with the knowledge and skills to productively navigate conversations about race, gender, and other aspects of social identities at work. Analyzes the structure of difficult conversations, investigates the research on conversational dynamics, and explores strategies for speaking up in organizations. Significant class time is devoted to experiential exercises. Weekly assignments include individual written reflections based on readings and research. For the final project, students write a short case, record a conversation, and assess their work. Restricted to second-year MBA students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"14:30","room":"E62-221"}]}],"url":"http://student.mit.edu/catalog/m15a.html#15.288"},{"code":"15.301","title":"People, Teams, and Organizations Laboratory","level":"U","description":"Develops appreciation for organizational dynamics and competence in navigating social networks, working in a team, demystifying rewards and incentives, leveraging the crowd, understanding change initiatives, and making sound decisions. Laboratory sessions emphasize the importance of the organizational context in influencing which individual styles and skills are effective by employing a wide variety of learning tools, from experiential learning to the more conventional discussion of written cases. Emphasizes use of behavioral science research methods to test hypotheses concerning decision-making, group behavior, and organizational behavior. Laboratory sessions provide instruction and practice in communication including report writing, team projects, and oral and visual presentation. 12 units may be applied to the General Institute Laboratory Requirement.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"E51-145"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"E51-145"}]},{"type":"Lab","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E51-151"},{"days":["F"],"start":"12:00","end":"13:00","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.301"},{"code":"15.311","title":"Organizational Processes","level":"G","description":"Enhances students' ability to take effective action in complex organizational settings by providing the analytic tools needed to analyze, manage, and lead the organizations of the future. Emphasizes the importance of the organizational context in influencing which individual styles and skills are effective. Employs a wide variety of learning tools, from experiential learning to the more conventional discussion of written cases. Centers on three complementary perspectives on organizations: the structural design, political, and cultural 'lenses' on organizations. Major project analyzes an actual organizational change using course frameworks. Restricted to first-year Sloan master's students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"14:30","room":"E62-223"},{"days":["R"],"start":"14:30","end":"16:00","room":"E62-223"},{"days":["R"],"start":"13:00","end":"14:30","room":"E51-325"},{"days":["R"],"start":"16:00","end":"17:30","room":"E62-223"},{"days":["R"],"start":"16:00","end":"17:30","room":"E51-325"},{"days":["R"],"start":"14:30","end":"16:00","room":"E51-325"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.311"},{"code":"15.318","title":"Discovering Your Leadership Signature","level":"G","description":"Trains students to understand and develop their unique way of leading — their leadership signature. Involves intensive self-assessment and interactive exercises to grow self-awareness and confidence in one's core leadership values and styles, and expand one's ability to consciously direct personal and professional growth. Students engage in exercises to reflect on their strengths and weaknesses that help and hinder their ability to lead authentically and effectively, and experiment inside and outside of class with new habits of thought and behavior. Assignments include creating and declaring a model of one's leadership signature, identifying development goals, and defining and taking initial steps towards one's desired future self. Grounded in readings from Jungian-oriented psychology, family systems and developmental psychology, and leadership literature.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"19:00","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.318"},{"code":"15.321","title":"Improvisational Leadership: In-the-Moment Leadership Skills","level":"G","description":"Designed to provide a practical understanding of the skills of improvisation and their application to leadership. Examines the essential elements of successful leadership, including creativity, emotional intelligence, adaptability, and the capacity to develop effective influence strategies and build strong teams. Cultivates students' ability to respond to the unexpected with confidence and agility. Each class offers a highly experiential learning laboratory where students practice a wide variety of improvised business scenarios, interactive exercises, and simulations.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"19:00","room":"E62-233"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.321"},{"code":"15.325","title":"Leadership in Disrupted Industries","level":"G","description":"Exposes students to accomplished leaders facing disruptive forces that are changing their industries, and explores leadership strategies to navigate disruption from the perspective of top management. Student panels prepare a detailed set of questions for each leader based on their organization and industry context. All students write two short papers — the first evaluating the leadership of a prior manager and the second explaining the planned changes to their own leadership approach.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"17:30","end":"19:00","room":"E62-262"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.325"},{"code":"15.337","title":"Teams Lab","level":"G","description":"Examination and application of frameworks, tools, and practices for effective teamwork and team leadership. Class sessions combine business cases, teaming scenarios, structured exercises, and peer-based reflection. Topics include navigating conflict, giving feedback, and addressing interpersonal challenges in team settings. Includes individual sessions with a professional executive coach throughout the term for guided reflection, feedback, and accountability. Restricted to 2nd year MBA students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"08:30","end":"11:30","room":"E62-221"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.337"},{"code":"15.342","title":"Organizations and Environments","level":"G","description":"Provides an introduction to research in 'organizations and environments,' an interdisciplinary domain of inquiry drawing primarily from sociology, and secondarily from economics, psychology, and political science. Seeks to understand organizational processes and outcomes in the surrounding economic, cultural, and institutional context in which they are situated. Also provides an introduction to the main groups that together form the Behavioral Policy Sciences (BPS) area of MIT/Sloan, including economic sociology, organization studies, work and employment, strategic management, global management, and technology, innovation, and entrepreneurship. Consists of four modules taught by faculty from each of the four BPS groups, as well as integrative sessions taught by the main instructor. Preference to first-year doctoral students in BPS.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:00","end":"16:00","room":"E62-446"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.342"},{"code":"15.360","title":"Entrepreneurship & Innovation Proseminar","level":"G","description":"Provides an overview of the process of entrepreneurship. Describes the entrepreneurial mindset, skillset, and way of operating to most efficiently and effectively create new innovation-driven ventures. Allows quick and efficient understanding of the resources available to guide students' entrepreneurial education journey. Aimed at a wide spectrum of students from little exposure to startup founders who want to enhance their skills or change industries. Format consists of lectures, discussions, and workshops. Emphasis is on building a common base of fundamental knowledge as well as community. Serves as an entry point to understand and access the rich body of resources in entrepreneurship at MIT. Enrollment in Silicon Valley Study Tour for the following spring term is required. No listeners; restricted to first-year MBA students in Sloan Entrepreneurship & Innovation (E&I) Certificate program.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"19:00","room":"E51-115"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.360"},{"code":"15.366","title":"Climate & Energy Ventures","level":"G","description":"Project-based approach to innovation and venture creation in the energy sector and sectors that can mitigate climate change. Explores how innovation and entrepreneurial concepts apply (or do not apply) to the significant opportunities in these industries. Working in teams, students create new ventures specifically for the energy sector or to address climate change. Lectures guide teams through key elements of their projects. 15.390 is recommended as a prerequisite.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"17:30","end":"20:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.366"},{"code":"15.369","title":"Corporate Entrepreneurship","level":"G","description":"Addresses the practical steps that can be taken to make existing organizations (corporations, non-profits, government, etc.) become more entrepreneurial. Uses a systematic approach to integrate lectures, exercises, guest speakers, and a team project. Application required.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"16:00","end":"19:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.369"},{"code":"15.371","title":"Innovation Teams","level":"G","description":"Introduces skills and capabilities for real-world problem solving to take technology from lab to societal impact: technical and functional exploration, opportunity discovery, market understanding, value economics, scale-up, intellectual property, and communicating/working for impact across disciplines. Students work in multidisciplinary teams formed around MIT research breakthroughs, with extensive in-class coaching and guidance from faculty, lab members, and select mentors. Follows a structured approach to innovating in which everything is a variable and the product, technology, and opportunities for new ventures can be seen as an act of synthesis. Teams gather evidence that permits a fact-based iteration across multiple application domains, markets, functionalities, technologies, and products, leading to a recommendation that maps a space of opportunity and includes actionable next steps to evolve the market and technology.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"15:00","room":"2-146"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.371"},{"code":"15.378","title":"Building an Entrepreneurial Venture: Advanced Tools and Techniques","level":"G","description":"Intensive, project-based subject intended for startup teams already working on building a new, high-impact venture. Applies advanced entrepreneurial techniques to build and iterate a venture in a time-compressed manner. Includes weekly coaching sessions with instructors and peers, as well as highly interactive and customized sessions that provide practical, in-depth coverage on key topics in entrepreneurship. Topics include venture creation, primary market research, product development, market adoption, team and culture, and scaling processes with constrained resources. Meets with 15.3781 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version; consult syllabus or instructor for specific details. Application required; consult instructor. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"17:30","end":"20:30","room":"E40-160"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.378"},{"code":"15.379","title":"Mobility Ventures: Driving Innovation in Transportation Systems","level":"G","description":"Explores technological, behavioral, policy, and systems-wide frameworks for innovation in transportation systems, complemented with case studies across the mobility spectrum, from autonomous vehicles to urban air mobility to last-mile sidewalk robots. Students interact with a series of guest lecturers from CEOs and other business and government executives who are actively reshaping the future of mobility. Interdisciplinary teams of students collaborate to deliver business plans for proposed mobility-focused startups with an emphasis on primary market research. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:30","end":"13:00","room":"E25-117"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.379"},{"code":"15.3791","title":"Mobility Ventures: Driving Innovation in Transportation Systems","level":"U","description":"Explores technological, behavioral, policy, and systems-wide frameworks for innovation in transportation systems, complemented with case studies across the mobility spectrum, from autonomous vehicles to urban air mobility to last-mile sidewalk robots. Students interact with a series of guest lecturers from CEOs and other business and government executives who are actively reshaping the future of mobility. Interdisciplinary teams of students collaborate to deliver business plans for proposed mobility-focused startups with an emphasis on primary market research. Students taking graduate version complete additional assignments. Preference to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:30","end":"13:00","room":"E25-117"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.3791"},{"code":"15.382","title":"Managing Innovation in Financial Institutions","level":"G","description":"Provides a practical guide to managing financial service firms such as robo advisors, sovereign funds, banks, insurance companies and retirement plans. Through case studies (e.g., cryptocurrency, micro lending, non-traded REITs, insurtech and ESG investing), focuses on innovative products and services to respond to unmet financial needs and disrupt the financial sector.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"E62-250"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.382"},{"code":"15.385","title":"Innovating for Impact","level":"G","description":"Provides a structured approach to innovation and entrepreneurship that creates business value while solving social and environmental problems. Covers physical domains of sustainability, e.g., waste, water, food, energy, and mobility, as well as social and human capital domains, such as health and education. Students explore case studies of critical decisions made in the early stages of an enterprise that help determine its impact. Considers perspective and tools applicable to the startup context or to new lines of business in existing enterprises.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-151"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.385"},{"code":"15.387","title":"Entrepreneurial Sales","level":"G","description":"Instruction in the fundamental Go-to-Market (GTM) motions and how to identify, build and execute on the right GTM motion(s) for technology startups. This includes not only building out a sales organization, but also the underlying processes and sales fundamentals required to measure results and sustain competitive advantage. This course is highly relevant to anyone interested in building a business or better understanding how to drive revenue from founding to scale.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"16:00","end":"17:30","room":"E51-325"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.387"},{"code":"15.388","title":"Venture Creation Tactics","level":"G","description":"Advanced, intensive, project-based subject intended for solo-founders or startup teams already working on building a new, high-impact venture, with a refined business plan. Supports students in their development of data to derisk the opportunity of pursuing a new venture full-time for founders, investors, and new recruits. This lab-style class promotes rapid experimentation by connecting the dots from the frameworks, concepts, and first principles covered in the introductory entrepreneurship subjects and guides students on how to tactically apply them in real-world situations. Topics include: advanced early go-to-market, enhanced target customer profile and persona development, digital advertising, outbound sales, UX design, rapid prototyping, recruiting early team members, and executing a fundraising plan. No listeners.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"08:30","end":"11:00","room":"E51-145"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.388"},{"code":"15.389","title":"Global Entrepreneurship Lab","level":"G","description":"Experiential study of the climate for innovation and determinants of entrepreneurial success. In teams of four, students work in collaboration with top management of a company to address real-world business challenges. Class sessions comprised of relevant content and dedicated project work meetings. Teams work on campus during the fall term and on-site/in-country with the company during IAP. Students gain insight as to how companies build, run, and scale a new enterprise. Focuses primarily on scale-ups operating in emerging and frontier markets. Restricted to MBA students; all other graduate students by permission of instructor only.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"E62-262"}]},{"type":"Recitation","options":[{"days":["R"],"start":"12:00","end":"13:00","room":"E62-262"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.389"},{"code":"15.390","title":"Entrepreneurship 101: Systematic Approach to New Venture Creation","level":"G","description":"Covers the process of identifying and quantifying market opportunities, then conceptualizing, planning, and starting a new, technology-based enterprise. Topics include opportunity assessment, the value proposition, the entrepreneur, legal issues, entrepreneurial ethics, the business plan, the founding team, seeking customers and raising funds. Students develop detailed business plans for a start-up. Intended for students who want to start their own business, further develop an existing business, be a member of a management team in a new enterprise, or better understand the entrepreneur and the entrepreneurial process. Meets with 15.3901 when offered concurrently.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E62-233"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.390"},{"code":"15.3901","title":"Entrepreneurship 101: Systematic Approach to New Venture Creation","level":"U","description":"Covers the process of identifying and quantifying market opportunities, then conceptualizing, planning, and starting a new, technology-based enterprise. Topics include opportunity assessment, the value proposition, the entrepreneur, legal issues, entrepreneurial ethics, the business plan, the founding team, seeking customers, and raising funds. Students develop detailed business plans for a start-up. Intended for students who want to start their own business, further develop an existing business, be a member of a management team in a new enterprise, or better understand the entrepreneur and the entrepreneurial process. Meets with 15.390 when offered concurrently. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E62-233"}]},{"type":"Recitation","options":[{"days":["F"],"start":"15:00","end":"16:00","room":"E40-160"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.3901"},{"code":"15.394","title":"Entrepreneurial Founding and Teams","level":"G","description":"Explores key organizational and strategic decisions in founding and building a new venture. Through a series of cases, readings, and activities, students examine the trade-offs and consequences of early founder decisions: whom to include in the founding team, how to allocate equity among co-founders, how to determine founder roles, how to hire and motivate early-employees, and whether to involve external investors. Aims to equip students with tools and frameworks to help them understand the implications of early decisions, and to build enduring resources that enable the venture to execute even if the original plan changes substantially. Meets with 15.3941 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version; consult syllabus or instructor for specific details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.394"},{"code":"15.3941","title":"Entrepreneurial Founding and Teams","level":"U","description":"Explores key organizational and strategic decisions in founding and building a new venture. Through a series of cases, readings, and activities, students examine the trade-offs and consequences of early founder decisions: whom to include in the founding team, how to allocate equity among co-founders, how to determine founder roles, how to hire and motivate early-employees, and whether to involve external investors. Aims to equip students with tools and frameworks to help them understand the implications of early decisions, and to build enduring resources that enable the venture to execute even if the original plan changes substantially. Meets with 15.394 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version; consult syllabus or instructor for specific details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.3941"},{"code":"15.399","title":"Entrepreneurship Lab","level":"G","description":"Project-based subject, in which teams of students from MIT and surrounding colleges work with startups on problems of strategic importance to the venture. Provides an introduction to entrepreneurship, and the action learning component allows students to apply their academic knowledge to the problems faced by entrepreneurial firms. Popular sectors include software, hardware, robotics, clean technology, and life sciences. Meets with 15.3991 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version; consult syllabus or instructor for specific details.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"19:00","room":"E62-250"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.399"},{"code":"15.401","title":"Managerial Finance","level":"G","description":"Introduction to finance from the perspective of business people and finance professionals. Designed to build effective decision-making skills based on sound financial knowledge, focusing on areas such as day-to-day operational issues and management, launching a startup, or negotiating option bonuses. Provides a firm grounding in the modern financial analysis underlying any decision, through three core themes: determining the value of a project, deciding how to finance a project, and managing its risk. Students also hone their ability to negotiate skillfully and speak intelligently about finance. Meets with 15.417 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version; consult syllabus or instructor for specific details. Some sections are restricted to graduate students only without the permission of the instructor. See syllabus url for further details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E62-233"},{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-395"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E52-164"},{"days":["M","W"],"start":"13:00","end":"14:30","room":"E52-164"},{"days":["M","W"],"start":"14:30","end":"16:00","room":"E52-164"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"E51-376"},{"days":["F"],"start":"11:00","end":"12:00","room":"VIRTUAL"},{"days":["W"],"start":"17:00","end":"18:00","room":"E51-145"},{"days":["W"],"start":"18:00","end":"19:00","room":"E51-145"},{"days":["F"],"start":"13:00","end":"14:00","room":"VIRTUAL"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.401"},{"code":"15.402","title":"Corporate Finance","level":"G","description":"Introduction to corporate finance which focuses on financing a firm through turbulence, for innovation, and for growth. Primarily uses case studies to introduce financial analytical tools needed to make real-world value-enhancing business decisions across many industries: how to decide which projects to invest in, how to finance those investments, and how to manage the cash flows of the firm. Meets with 15.418 when offered concurrently.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"E51-345"},{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.402"},{"code":"15.403","title":"Introduction to the Practice of Finance","level":"G","description":"Explores various career paths within the finance industry, from private equity to public policy, FinTech to social impact, investment banking to investment management, corporate finance to venture capital. Students engage with industry professionals about the challenges they face and how their part of the industry is changing. They also network with peers to discover the challenges and rewards associated with various careers, and explore how coursework connects with industry practice. Priority given to students in the MIT Sloan Finance Certificate program.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"17:30","room":"E62-276"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.403"},{"code":"15.414","title":"Financial Management","level":"G","description":"Provides a rigorous introduction to corporate finance and capital markets, with an emphasis on applications vital to corporate managers. Exposes students to the major financial decisions made by leaders within a firm and to the ways the firm interacts with investors, with a focus on valuation. Topics include project and company valuation, measuring risk and return, stock pricing, corporate financing policy, the cost of capital, and risk management. Presents a broad overview of both theory and practice. Restricted to Sloan Fellow MBAs.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E51-149"},{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.414"},{"code":"15.417","title":"Laboratory in Investments","level":"U","description":"Introduction to finance with a lab component that puts theory into practice. Designed to build effective decision-making skills for business and to develop hands-on analytical techniques that are used by investment managers and traders. Lectures provide a firm grounding in financial analysis--determining the value of a decision, deciding how to finance a project, and assessing its risk. Lab sessions introduce students to modern tools and methods used in financial markets. Through team projects, students develop and test asset-pricing models, forecasting methods, and investment strategies using real-world market data. Provides instruction in writing and speaking from a financial perspective. Meets with 15.401 when offered concurrently.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E62-233"},{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-395"}]},{"type":"Lab","options":[{"days":["F"],"start":"13:00","end":"16:00","room":"E62-221"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"E51-376"},{"days":["F"],"start":"11:00","end":"12:00","room":"VIRTUAL"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.417"},{"code":"15.418","title":"Laboratory in Corporate Finance","level":"U","description":"Introduction to corporate finance. Classroom portion primarily uses case studies to introduce financial analytical tools needed to make real-world value-enhancing business decisions across many industries: how to decide which projects to invest in, how to finance those investments, and how to manage the cash flows of the firm. Laboratory sessions are organized around team valuation projects, such as valuation of an oil field and analysis of a potential merger between two public firms proposed by student teams. Projects require extensive use of financial databases. Laboratory sessions also provide instruction on writing and speaking on financial topics. Meets with 15.402 when offered concurrently.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"E51-345"},{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-335"}]},{"type":"Lab","options":[{"days":["F"],"start":"10:00","end":"11:30","room":"E62-221"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.418"},{"code":"15.425","title":"Corporate Finance","level":"G","description":"Foundational, applied course providing instruction in the tools and techniques of corporate financial management from the perspective of the CFO. Case studies present the financial tools needed to make value-enhancing business decisions: how to decide which projects to invest in, how to finance those investments, and how to manage the cash flows of the firm. Topics include capital budgeting, investment decisions and valuation; working capital management, security issues; dividend policy; optimal capital structure; and real options analysis. Restricted to students in the Master of Finance Program.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"10:00","room":"E62-276"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E62-276"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.425"},{"code":"15.426","title":"Real Estate Finance and Investment","level":"G","description":"Concepts and techniques for analyzing financial decisions in commercial property development and investment. Topics include property income streams, discounted cash flow, equity valuation, leverage and income tax considerations, development projects, and joint ventures. An introduction to real estate capital markets as a source of financing is also provided. Limited to graduate students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"9-354"}]},{"type":"Recitation","options":[{"days":["M"],"start":"16:00","end":"18:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.426"},{"code":"15.431","title":"Entrepreneurial Finance and Venture Capital","level":"G","description":"Examines the elements of entrepreneurial finance, focusing on technology-based start-up ventures, and the early stages of company development. Addresses key questions which challenge all entrepreneurs: how much money can and should be raised; when should it be raised and from whom; what is a reasonable valuation of a company; and how funding, employment contracts and exit decisions should be structured. Aims to prepare students for these decisions, both as entrepreneurs and venture capitalists. In-depth analysis of the structure of the private equity industry. Meets with 15.4311 when offered concurrently. Expectations and evaluation criteria for graduate students will differ from those of undergraduates; consult syllabus or instructor for specific details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-315"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E51-315"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.431"},{"code":"15.4311","title":"Entrepreneurial Finance and Venture Capital","level":"U","description":"Examines the elements of entrepreneurial finance, focusing on technology-based start-up ventures, and the early stages of company development. Addresses key questions which challenge all entrepreneurs: how much money can and should be raised; when should it be raised and from whom; what is a reasonable valuation of a company; and how funding, employment contracts and exit decisions should be structured. Aims to prepare students for these decisions, both as entrepreneurs and venture capitalists. In-depth analysis of the structure of the private equity industry. Meets with 15.431 when offered concurrently. Expectations and evaluation criteria for graduate students will differ from those of undergraduates; consult syllabus or instructor for specific details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-315"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E51-315"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.4311"},{"code":"15.433","title":"Financial Markets","level":"G","description":"Provides students with a solid understanding of key financial markets and the empirical skills and tools used to support decision making. Employs an in-depth, empirically-driven exploration of markets, including equity, fixed income, and derivatives.  Students apply real-world financial data to test and understand financial models, focusing on key risk factors and risk management concerns in these markets, along with the quantitative tools used to analyze risk. Discusses major institutions and players involved in each market, the evolution of the markets, and issues such as liquidity. Meets with 15.4331 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version; consult syllabus or instructor for specific details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E52-164"},{"days":["T","R"],"start":"10:00","end":"11:30","room":"E52-164"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.433"},{"code":"15.4331","title":"Financial Markets","level":"U","description":"Provides students with a solid understanding of key financial markets and the empirical skills and tools used to support decision making. Employs an in-depth, empirically-driven exploration of markets, including equity, fixed income, and derivatives.  Students apply real-world financial data to test and understand financial models, focusing on key risk factors and risk management concerns in these markets, along with the quantitative tools used to analyze risk. Discusses major institutions and players involved in each market, the evolution of the markets, and issues such as liquidity. Meets with 15.433 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version; consult syllabus or instructor for specific details. Preference to Course 15 students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E52-164"},{"days":["T","R"],"start":"10:00","end":"11:30","room":"E52-164"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.4331"},{"code":"15.434","title":"Advanced Corporate Finance","level":"G","description":"Exposes students to advanced application of tools and techniques of corporate financial management. Covers complex valuations, modelling of capital structure decisions, financial restructuring, analysis and modelling of merger transactions, and real options. Additional topics include security design, choice of financial instruments, pricing of convertible bonds and convertible preferred stocks. Also covers project finance and other hybrid financing facilities.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"10:00","room":"E51-145"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E51-145"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.434"},{"code":"15.4341","title":"Advanced Corporate Finance","level":"U","description":"Exposes students to advanced application of tools and techniques of corporate financial management. Covers complex valuations, modelling of capital structure decisions, financial restructuring, analysis and modelling of merger transactions, and real options. Additional topics include security design, choice of financial instruments, pricing of convertible bonds and convertible preferred stocks. Also covers project finance and other hybrid financing facilities.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"10:00","room":"E51-145"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E51-145"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.4341"},{"code":"15.450","title":"Analytics of Finance","level":"G","description":"Introduces a set of modern analytical tools that specifically target finance applications. Topics include statistical inference, financial time series, event study analysis, and basic machine learning techniques for forecasting. Focuses on how to apply these tools for financial and macro forecasting, quantitative trading, risk management, and fintech innovations such as Kensho's 'financial answer machine'' and big-data lending platforms. 15.457 is a more advanced version of 15.450. Students with solid background in statistics and proficiency in programming are encouraged to register for 15.457.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E62-233"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"E51-145"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.450"},{"code":"15.451","title":"Investment Management Lab","level":"G","description":"Provides a unique opportunity to tackle original research problems in capital market analysis and investment management that have been posed by leading experts from the financial community. Students are assigned to teams, and each team is assigned one such problem. Teams present their solutions at a seminar which is attended by representatives of the sponsoring organization and open to the entire MIT community. Not open to students from other institutions.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"18:00","room":"E52-164"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.451"},{"code":"15.456","title":"Financial Engineering","level":"G","description":"Exposes students to the cutting edge of financial engineering. Includes a deep immersion into 'how things work,' where students develop and test sophisticated computational models and solve highly complex financial problems. Students are required to complete two advanced group projects. Covers stochastic modeling, dynamic optimization, mathematical programming, stochastic calculus, and Monte Carlo simulation, presented through applications such as dynamic asset pricing and investment management, market equilibrium and portfolio choice with frictions and constraints, market microstructure models, and risk management. Assumes a solid undergraduate-level background in calculus, probability, statistics, and programming, and includes a substantial coding component. Classroom examples presented using Python and R.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E62-276"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E51-145"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.456"},{"code":"15.457","title":"Advanced Analytics of Finance","level":"G","description":"Introduces a set of modern analytical tools that specifically target finance applications. Topics include statistical inference, financial time series, event study analysis, and machine learning techniques. Focuses on how to apply these tools for financial and macro forecasting, quantitative trading, risk management, and fintech innovations such as big-data lending and robo-advisors. 15.457 is a more advanced version of 15.450. Students with a solid background in statistics and proficiency in programming are encouraged to register for 15.457.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"E62-233"}]},{"type":"Recitation","options":[{"days":["F"],"start":"15:00","end":"16:00","room":"E51-145"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.457"},{"code":"15.470","title":"Asset Pricing","level":"G","description":"Provides a foundation in the neoclassical theory of finance that underlies more advanced study. Covers arbitrage asset pricing, optimal consumption-portfolio choices, neo-classic theory of corporate finance, static equilibrium models of asset pricing, asymmetric information, and dynamic modeling. Prepares students for further study of asset pricing theories, corporate finance and econometric work in finance. Primarily for doctoral students in finance, economics, and accounting.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"16:00","end":"17:30","room":"E62-650"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E62-350"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.470"},{"code":"15.472","title":"Advanced Asset Pricing","level":"G","description":"Focuses on developing, solving, estimating, and empirically evaluating theoretical models of asset prices and financial markets, as well as their microeconomic foundations and macroeconomic implications. Discusses theory and econometric methods, the state of the literature, and recent developments and empirical evidence. Covers topics such as cross-sectional and time-series models, consumption-based and intermediary-based models, financial institutions, household finance, housing, behavioral finance, financial crises, market structure, and continuous-time tools and applications. Primarily for doctoral students in finance, economics, and accounting.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"16:00","end":"17:30","room":"E62-650"}]},{"type":"Recitation","options":[{"days":["M"],"start":"18:00","end":"19:30","room":""}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.472"},{"code":"15.474","title":"Current Topics in Finance","level":"G","description":"Faculty present their current research in a wide variety of topics in finance. Provides a rapid overview of the literature, an in-depth presentation of selected contributions, and a list of potential research ideas for each topic. Faculty rotate every year to cover new topics. Primarily for doctoral students in accounting, economics, and finance.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"10:30","end":"12:00","room":"E62-650"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.474"},{"code":"15.475","title":"Current Research in Financial Economics","level":"G","description":"Advanced seminar intended for PhD students interested in finance. Topics and papers vary by term, following the latest research in academia and in correlation with the weekly finance faculty research seminar. Each week, students will critically review the contributions, method of analysis, and presentation of evidence of existing research; one session is devoted to preparing for the finance seminar, while the other session discusses further work on the same topic. Restricted to doctoral students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"12:00","end":"13:00","room":"E62-687"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.475"},{"code":"15.483","title":"Consumer Finance and FinTech","level":"G","description":"Explores consumer finance and how disruptors use technology to change business models, products, and competition. A review of the major consumer sectors ? consumer credit, investing, trading, payments, and insurance ? provides students with a solid understanding of how technology, products, funding, regulation, and customer experience shape these markets. Students evaluate competitive dynamics amongst FinTech startups, 'Big Finance,' and 'Big Tech.' Topics include: payment apps, neo-banks, mortgage originators, brokerage apps, robo-advisors, peer-to-peer lending, insurtech, crypto assets, and prediction markets.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-315"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.483"},{"code":"15.497","title":"FinTech Ventures","level":"G","description":"Provides a unique opportunity to work through the nuts and bolts of developing a FinTech startup. Students present ideas, ranging from well-thought-out concepts to emerging ones. Students coalesce around the top ideas to form teams. Each week, a new speaker (entrepreneur, legal expert, venture capitalist) addresses relevant topics, while students present progress reports and receive advice and feedback as they develop their plan for the 'Demo Day.' Teams then deliver a final pitch in front of a group of investors. A financial background is not required; alternative (legal, financial, technical, operations, etc.) backgrounds are encouraged to apply, individually or as part of a team. Enrollment by application only.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"17:30","end":"20:30","room":"E62-223"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.497"},{"code":"15.501","title":"Corporate Financial Accounting","level":"U","description":"Preparation and analysis of financial statements. Focuses on why financial statements take the form they do, and how they can be used in evaluating corporate performance and solvency and in valuation of corporate securities. Introduces concepts from finance and economics (e.g., cash flow discounting and valuation) and explains their relation to, and use in, accounting. Students taking the graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E51-395"},{"days":["T","R"],"start":"11:30","end":"13:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.501"},{"code":"15.515","title":"Financial Accounting","level":"G","description":"An intensive introduction to the interpretation of financial information. Adopts a decision-maker perspective of accounting by emphasizing the relation between accounting data and the underlying economic events generating them. Class sessions are a mixture of lecture and case discussion. Assignments include textbook problems, analysis of financial statements, and cases. Restricted to first-year Sloan master's students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E62-276"},{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-335"},{"days":["T","R"],"start":"08:30","end":"10:00","room":"E62-223"},{"days":["T","R"],"start":"10:00","end":"11:30","room":"E62-276"},{"days":["T","R"],"start":"10:00","end":"11:30","room":"E51-335"},{"days":["T","R"],"start":"10:00","end":"11:30","room":"E62-223"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"VIRTUAL"},{"days":["F"],"start":"11:00","end":"12:00","room":"VIRTUAL"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.515"},{"code":"15.516","title":"Corporate Financial Accounting","level":"G","description":"See description under subject 15.501. If subject is oversubscribed, priority is given to Course 15 students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E51-395"},{"days":["T","R"],"start":"11:30","end":"13:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.516"},{"code":"15.521","title":"Accounting Information for Decision Makers","level":"G","description":"Focuses on how organizations use granular-level information from their accounting systems on a day-to-day basis for two purposes -- making decisions and evaluating those decisions after the fact. The primary audience is students who intend to work as managers or management consultants. Featuring real-world situations from diverse operating environments, course content emphasizes practical skills that can be applied across various functional areas within organizations.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-149"},{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.521"},{"code":"15.535","title":"Business Analysis Using Financial Statements","level":"G","description":"Focuses on the strategic, financial, and accounting analysis of a company by means of historical financial statement data. Also studies financial statement forecasting along with a specific application of forecasting - valuation. Concepts are applied to a number of decision-making contexts, including securities analysis, credit analysis, merger analysis, and company performance assessment.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-395"},{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.535"},{"code":"15.539","title":"Doctoral Seminar in Accounting","level":"G","description":"Designed primarily for doctoral students in accounting and related fields. The reading list consists of accounting research papers. Objective is to introduce research topics, methodologies, and developments in accounting, and train students to do independent research.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:30","end":"16:30","room":"E62-687"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.539"},{"code":"15.540","title":"Theory Studies in Accounting Research","level":"G","description":"Exposes PhD students to theoretical foundations of cutting-edge research in accounting. Rotating modules cover topics on disclosure, contracting, compensation, asset pricing, and investments.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"12:00","end":"13:00","room":"E62-687"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.540"},{"code":"15.561","title":"Digital Revolution: From Foundations to Future Trends","level":"G","description":"Emphasizes programming in scripting languages (e.g., Python) within the context of emerging trends that underlie current and future uses of digital technologies in business. Provides a solid grasp of programming basics and the foundations of computing. Other topics include web technologies, database systems, digital experimentation (A/B testing), crowdsourcing, digital marketplaces, distributed ledger technologies, and AI.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E62-250"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.561"},{"code":"15.563","title":"Artificial Intelligence for Business","level":"G","description":"Explores how to design and evaluate products and policy based on artificial intelligence. Provides a functional (as opposed to mechanistic) understanding of the emerging technologies underlying AI. Presents AI's opportunities and risks and how to create conditions under which its deployment can succeed. No technical background required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-345"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.563"},{"code":"15.572","title":"Analytics Lab: Action Learning Seminar on Analytics, Machine Learning, and the Digital Economy","level":"G","description":"Student teams design and deliver a project based on the use of analytics, machine learning, large data sets, or other digital innovations to create or transform a business or other organization. Teams may be paired up with an organization or propose their own ideas and sites for the project. Culminates with presentation of results to an audience that includes IT experts, entrepreneurs, and executives.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"17:30","room":"E62-276"}]},{"type":"Recitation","options":[{"days":["R"],"start":"17:30","end":"19:00","room":"E62-276"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.572"},{"code":"15.576","title":"Research Seminar in Information Technology and Organizations: Social Perspectives","level":"G","description":"Examines the assumptions, concepts, theories, and methodologies that inform research into the social aspects of technology. Extensive reading and discussion of research literature aimed at exploring the multiple social phenomena surrounding the development, implementation, use and implications of information technology in organizations. Restricted to doctoral students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:30","end":"17:30","room":"E62-550"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.576"},{"code":"15.618","title":"Startups and the Law","level":"G","description":"The legal framework of entrepreneurship and innovation. Key law-sensitive junctures in launching and growing a startup: assembling a team, organizing a business entity, ownership and compensation, early financing, managing contracts and employees, business distress and winding down, and selling a company. Cutting-edge technologies and intellectual property rights. Designed for those who may start or work in such ventures; or are engaged in research with potential for commercial or social impact; or are otherwise attempting to advance an innovation from idea to impact. No prior knowledge of law expected. Meets with 15.6181 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"17:30","end":"19:00","room":"E51-345"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.618"},{"code":"15.622","title":"The Law of Artificial Intelligence and Big Data","level":"G","description":"Focuses on the law of artificial intelligence, big data, and related cutting-edge digital technologies. Considers the law's impact on the development and adoption of these technologies, and the legal response to beneficial and mischievous impacts. Emphasis on current issues, but topics generally include the legal frameworks of intellectual property rights, cybersecurity, privacy, bias, fintech, fair competition and fair dealing in digital markets, and political discourse on social media. Gives special attention to the legal concerns of those planning careers built on cutting-edge skills, and of managers, entrepreneurs, scientists, and engineers bringing innovations from ideas to impact. Explores how to find and make good use of legal advice. Meets with 15.6221 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"17:30","end":"19:00","room":"E51-345"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.622"},{"code":"15.655","title":"Law, Technology, and Public Policy","level":"G","description":"Examines how law, economics, and technological change shape public policy, and how law can sway technological change; how the legal system responds to environmental, safety, energy, social, and ethical problems; how law and markets interact to influence technological development; and how law can affect wealth distribution, employment, and social justice. Covers energy/climate change; genetic engineering; telecommunications and the role of misinformation; industrial automation; effect of regulation on technological innovation; impacts of antitrust law on innovation and equity; pharmaceuticals; nanotechnology; cost/benefit analysis as a decision tool; public participation in governmental decisions affecting science and technology; corporate influence on technology and welfare; and law and economics as competing paradigms to encourage sustainability. Students taking graduate version explore subject in greater depth.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"E51-057"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.655"},{"code":"15.657","title":"Technology, Globalization, and Sustainable Development","level":"G","description":"Investigates sustainable development, taking a broad view to include not only a healthy economic base, but also a sound environment, stable and rewarding employment, adequate purchasing power and earning capacity, distributional equity, national self-reliance, and maintenance of cultural integrity. Explores national, multinational, and international political and legal mechanisms to further sustainable development through transformation of the industrial state. Addresses the importance of technological innovation and the financial crisis of 2008 and the emergence of the Covid-19 pandemic, Russia's invasion of Ukraine, and inflation, as well as governmental interventions to reduce inequality.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"16:00","end":"18:30","room":"E51-376"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.657"},{"code":"15.662","title":"People and Profits: Shaping  the Future of Work","level":"G","description":"Examines managing work in the 21st century in the interests of both people and profits through the context of rising inequality, technological change, globalization, and the growth of the gig economy. Students evaluate various business and policy interventions intended to improve work through critical analysis of the evidence, interviews with workers and evaluations of firms, and guest speakers. Guests include business leaders at leading-edge firms and labor leaders experimenting with new ways of providing workers a voice in the workplace. Draws on materials from the MIT Task Force on Work of the Future and the online course Shaping Work of the Future.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"E51-315"},{"days":["M","W"],"start":"13:00","end":"14:30","room":"E62-233"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.662"},{"code":"15.665","title":"Power and Negotiation","level":"G","description":"Provides understanding of the theory and processes of negotiation as practiced in a variety of settings. Designed for relevance to the broad spectrum of bargaining problems faced by the manager and professional. Allows students an opportunity to develop negotiation skills experientially and to understand negotiation in useful analytical frameworks. Emphasizes simulations, exercises, role playing, and cases.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"16:00","room":"E62-276"},{"days":["T"],"start":"16:30","end":"19:30","room":"E62-276"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.665"},{"code":"15.671","title":"U-Lab: Transforming Self, Business and Society","level":"G","description":"Experiential opportunity to practice new leadership skills, such as deep listening, being present (mindfulness), and generative dialogue. In weekly coaching circles, each student has one full session to present their current leadership edge and receive feedback from peer coaches. Includes an additional action learning project.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"17:30","end":"21:00","room":"E62-233"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.671"},{"code":"15.674","title":"Leading Creative Teams","level":"G","description":"Prepares students to lead teams charged with developing creative solutions in engineering and technical environments. Grounded in research but practical in focus, equips students with leadership competencies such as building self-awareness, motivating and developing others, creative problem solving, influencing without authority, managing conflict, and communicating effectively. Teamwork skills include how to convene, launch, and develop various types of teams, including project teams. Learning methods emphasize personalized and experiential skill development. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.674"},{"code":"15.677","title":"Labor Markets and Employment Policy","level":"G","description":"Research-based examination of how labor markets work — and how they have evolved over time — through trends such as rising income inequality, technological change, globalization, falling worker power, and the fissuring of the workplace. Through reading and engaging with economics research papers, students use theoretical frameworks and rigorous empirical evidence to analyze public policy interventions in the labor market, including unemployment insurance, minimum wage, unions, family leave, anti-discrimination policies, and workforce development. Preference to graduate and PhD students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"16:00","room":"E62-346"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.677"},{"code":"15.681","title":"From Analytics to Action","level":"G","description":"Develops appreciation for organizational dynamics and competence in navigating social networks, working in a team, demystifying rewards and incentives, leveraging the crowd, understanding change initiatives, and making sound decisions. Restricted to Master of Business Analytics students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"11:30","room":"E62-233"}]}],"url":"http://student.mit.edu/catalog/m15b.html#15.681"},{"code":"15.739","title":"Discovering Your Leadership Signature","level":"G","description":"Introspective course that helps students understand and develop their unique way of leading, i.e., their leadership signature. Students delve deeply into their patterns of leadership to understand what helps and hinders them in becoming a better leader. Substantial time spent learning how to effectively tell leadership stories and examine leadership identity, drawing on theory from the leadership literature, family systems, developmental psychology, personality psychology, and organizational change. Builds on the four capabilities (4-CAPS+) model and includes case studies, reflection, video analysis, and storytelling. Restricted to Executive MBA and Sloan Fellow MBA students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"19:00","room":"E62-262"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.739"},{"code":"15.761","title":"Introduction to Operations Management","level":"G","description":"Imparts concepts, techniques, and tools to design, analyze, and improve core operational capabilities and apply them to a broad range of domains and industries. Emphasizes the effect of uncertainty in decision-making, as well as the interplay among high-level financial objectives, operational capabilities, and people and organizational issues. Covers topics in capacity analysis, process design, process and business innovation, inventory management, risk pooling, supply chain coordination, sustainable operations, quality management, operational risk management, pricing and revenue management. Underscores how these topics are integrated with different functions of the firm. Case studies and simulation games provide experience in applying central concepts and techniques to solve real-world business challenges. Meets with 15.7611 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version. Summer section is primarily for Leaders for Global Operations students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E62-276"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"E51-315"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.761"},{"code":"15.767","title":"Introduction to Healthcare Delivery in the United States","level":"G","description":"Focuses on the business challenges and opportunities to deliver high-quality and reasonably priced health services, mainly in the United States. Provides an opportunity to interact with guest speakers and senior executives from the health sector. Topics include: aspects of healthcare delivery operations and how they are affected by healthcare reform policies, alternative payment models, population health perspectives, and social determinants of health. Discussions include examples from the ongoing healthcare-related work of Sloan faculty, as well as the potential for analytics and digitization to impact healthcare delivery. Provides a broad perspective on various career paths, such as consulting, entrepreneurship, delivery system management, and digital innovation development.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E51-376"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.767"},{"code":"15.768","title":"Management of Services: Creating Value for Customers, Employees, and Investors","level":"G","description":"Focuses on how companies can use operational principles to create value for customers, employees, and investors simultaneously. Case-based subject that emphasizes systems perspective and leadership in operations versus the use of specific analytical tools (e.g., queuing theory, inventory management, process analysis) that were covered in the pre- or co-requisite. Cases include a range of service operations contexts including healthcare, hospitality, retailing, food service, pest control, and financial services.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E62-262"},{"days":["M","W"],"start":"14:30","end":"16:00","room":"E62-262"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.768"},{"code":"15.770","title":"Logistics Systems","level":"G","description":"Provides an introduction to supply chain management from both analytical and practical perspectives. Taking a unified approach, students develop a framework for making intelligent decisions within the supply chain. Covers key logistics functions, such as demand planning, procurement, inventory theory and control, transportation planning and execution, reverse logistics, and flexible contracting. Explores concepts such as postponement, portfolio management, and dual sourcing. Emphasizes skills necessary to recognize and manage risk, analyze various tradeoffs, and model logistics systems. SCM.271 meets with SCM.260, but has fewer assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.770"},{"code":"15.774","title":"AI for Operations","level":"G","description":"Equips students with the essential concepts, techniques, and tools to effectively analyze and enhance data-driven decision-making. Through a strong emphasis on artificial intelligence, students apply machine learning, deep learning, optimization, and reinforcement learning to real-world challenges across supply chains, retail, online platforms, healthcare, and beyond. Includes a final project in which students design and implement AI-powered solutions to complex operational problems. Prepares students to lead in a world where data and AI are transforming the future of operations.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-345"}]},{"type":"Recitation","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.774"},{"code":"15.776","title":"Intensive Hands-on Deep Learning","level":"G","description":"Fast-paced introduction to deep learning, the engine behind modern artificial intelligence, with an emphasis on developing a practical understanding of how to build models to solve complex problems involving unstructured data. Rapid introduction to deep neural networks and their training. Emphasis on language models, focused on masked and generative modeling and vision models (using diffusions and transformers). Model adaptation via fine-tuning, RL-based training (eg., RLHF, GRPO, etc.). System design concepts including retrieval augmented generation and agentic system design. Prior familiarity with Python and fundamental machine learning concepts (such as training/validation/testing, overfitting/underfitting, and regularization) required. Preference to Sloan Master of Business Analytics students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-345"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.776"},{"code":"15.777","title":"Healthcare Lab: Introduction to Healthcare Delivery in the United States","level":"G","description":"Focuses on the business challenges and opportunities to deliver high-quality and reasonably-priced health services, mainly in the United States. Provides an opportunity to interact with guest speakers and senior executives from the health sector. Topics include aspects of healthcare delivery operations and how they are affected by healthcare reform policies, alternative payment models, population health perspectives, and social determinants of health. Discussions include examples from the ongoing healthcare-related work of Sloan faculty, as well as the potential for analytics and digitization to impact healthcare delivery. Provides a broad perspective on various career paths, such as consulting, entrepreneurship, delivery system management, and digital innovation development. Student teams work with a provider, supplier or healthcare-related startup organization on an applied project. Includes on-site work during fall and IAP.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E51-376"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"VIRTUAL"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.777"},{"code":"15.780","title":"Analytics of Operations Management","level":"U","description":"Introduces core concepts in data-driven modeling that inform and optimize business decisions under uncertainty. Covers models and frameworks, such as machine learning, time series forecasting, dynamic programming, stochastic optimization, and multi-armed bandits. Draws on real-world applications, with several examples from retail, healthcare, logistics, supply chain, and public sector.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:30","end":"13:00","room":"E62-250"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"E62-250"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.780"},{"code":"15.792","title":"Global Operations Leadership Seminar","level":"G","description":"Integrative forum in which worldwide leaders in business, finance, government, sports, and education share their experiences and insights with students aspiring to run global operations. Students play a large role in managing the seminar. Preference to LGO students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"18:00","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.792"},{"code":"15.799","title":"Workshop in Operations Management","level":"G","description":"Presentations by faculty, doctoral students, and guest speakers of ongoing research relating to current issues in operations management, including reports of research projects (proposed or in progress) and informal discussions of recent literature dealing with subjects of special interest to participants. Primarily for doctoral students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:30","end":"13:00","room":"E62-550"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.799"},{"code":"15.814","title":"Marketing Innovation","level":"G","description":"Develops the skills necessary to market innovations, including new products, services, and concepts. Covers how to gain market intelligence, target the right customers, choose the right brand positioning, and combine analytics, frameworks, and research for maximum potential. Emphasizes both marketing theory and practice; students work in teams to market real innovations. Subject updated continually to highlight the latest use of artificial intelligence for marketing.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E62-250"},{"days":["M","W"],"start":"14:30","end":"16:00","room":"E62-250"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.814"},{"code":"15.818","title":"Pricing","level":"G","description":"Framework for understanding pricing strategies and analytics, with emphasis on entrepreneurial pricing. Topics include economic value analysis, elasticities, customization, complementary products, pricing in platform markets, and anticipating competitive responses.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E62-250"},{"days":["T","R"],"start":"13:00","end":"14:30","room":"E52-164"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E52-164"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.818"},{"code":"15.830","title":"Enterprise Management Lab","level":"G","description":"Lays the foundation for the Enterprise Management (EM) Certificate by developing students' ability to apply integrated management perspectives and practices through action-learning. Small teams of students deliver quality deliverables by working on projects for large organizations and emergent innovators that integrate marketing, operations, and/or strategy. Students engage with faculty mentors and guest faculty speakers from marketing, strategy, and operations. Promotes a holistic cross-functional approach to addressing business issues. Significant class time allocated to team collaboration on projects. Students must register for both the fall term and IAP. Restricted to students eligible for the MIT Sloan Enterprise Management Certificate.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"19:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.830"},{"code":"15.833","title":"Business-to-Business Marketing","level":"G","description":"Applies marketing concepts, analyses and tools used in business-to-business (B2B) marketing. Develops an understanding of customer value management and value quantification as a strategy for delivering superior value to targeted business segments while maintaining equitable returns. Focuses on B2B pricing, brand building, web and technology facilitation of the supply chain, and customer relationship management. Underscores sales force management within the context of go-to-market strategy; however, does not address selling per se. Discusses various B2B contexts, such as products and services, for- and non-profits, and domestic and global markets. Emphasizes applications in technology and healthcare domains. Includes value-based pricing project, case studies, applied exercises, and readings.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"E62-250"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.833"},{"code":"15.838","title":"Research Seminar in Marketing","level":"G","description":"Seminar on current marketing literature and current research interests of faculty and students. Topics such as marketing models, consumer behavior, competitive strategy, marketing experimentation, and game theory. Restricted to doctoral students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:30","end":"12:30","room":"E62-587"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.838"},{"code":"15.839","title":"Workshop in Marketing","level":"G","description":"Presentations by faculty, doctoral students, and guest speakers of ongoing research relating to current issues in marketing. Topics: reports of research projects (proposed or in progress) and informal discussions of recent literature dealing with subjects of special interest to participants. Restricted to doctoral students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"11:30","end":"13:00","room":"E62-550"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.839"},{"code":"15.871","title":"Introduction to System Dynamics","level":"G","description":"Introduction to systems thinking and system dynamics modeling applied to strategy, organizational change, and policy design. Students use simulation models, management flight simulators, and case studies to develop conceptual and modeling skills for the design and management of high-performance organizations in a dynamic world. Case studies of successful applications of system dynamics in growth strategy, management of technology, operations, public policy, product development, and others. Principles for effective use of modeling in the real world. Meets with 15.873 first half of term when offered concurrently. Students taking 15.871 complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E62-223"},{"days":["M","W"],"start":"14:30","end":"16:00","room":"E62-223"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:30","room":"E51-335"},{"days":["F"],"start":"14:30","end":"16:00","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.871"},{"code":"15.873","title":"System Dynamics for Business and Policy","level":"G","description":"Focuses on developing the skills and tools needed to successfully apply systems thinking and simulation modeling in diverse real-world settings, including growth strategy, management of technology, operations, public policy, product development, supply chains, forecasting, project management, process improvement, service operations, and platform-based businesses, among others. Uses simulation models, management flight simulators, and case studies to deepen conceptual and modeling skills beyond what is introduced in 15.871. Exploring case studies of successful applications, students develop proficiency in how to use qualitative and quantitative data to formulate and test models, and how to work effectively with senior executives to successfully implement change. Prepares students for further work in the field. Meets with 15.871 in first half of term when offered concurrently. Students taking 15.871 complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E62-223"},{"days":["M","W"],"start":"14:30","end":"16:00","room":"E62-223"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:30","room":"E51-335"},{"days":["F"],"start":"14:30","end":"16:00","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.873"},{"code":"15.8731","title":"System Dynamics: Tools for Solving Complex Problems","level":"U","description":"Introduction to field of system dynamics. Builds on ideas of control theory to understand dynamics of social, technological and organizational systems. Focuses on developing skills and tools needed to successfully apply systems thinking and simulation modeling in diverse real-world settings, including sustainability, strategy, project management, product development, public policy, healthcare, forecasting, platform-based businesses, and others. Utilizes simulation models, management flight simulators, and case studies to deepen conceptual and modeling skills. Develops proficiency in using qualitative and quantitative data to formulate and test models and how to work effectively with policy makers and executives to successfully implement change. Meets with 15.873 when offered concurrently. Expectations and evaluation criteria may differ for students taking the graduate version; consult syllabus or instructor for specific details.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E62-223"},{"days":["M","W"],"start":"14:30","end":"16:00","room":"E62-223"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:30","room":"E51-335"},{"days":["F"],"start":"14:30","end":"16:00","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.8731"},{"code":"15.874","title":"People and the Planet: Environmental Governance and Science","level":"U","description":"Introduces governance and science aspects of complex environmental problems and approaches to solutions. Introduces quantitative analyses and methodological tools to analyze environmental issues that have human and natural components. Demonstrates concepts through a series of in-depth case studies of environmental governance and science problems. Students develop writing, quantitative modeling, and analytical skills in assessing environmental systems problems and developing solutions. Through experiential activities, such as modeling and policy exercises, students engage with the challenges and possibilities of governance in complex, interacting systems, including biogeophysical processes and societal and stakeholder interactions.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:30","end":"12:30","room":"54-820"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.874"},{"code":"15.879","title":"Research Seminar in System Dynamics","level":"G","description":"Doctoral seminar in system dynamics modeling, with a focus on building advanced modeling and research skills. Topics vary from year to year and may include: classic works in dynamic modeling from various disciplines (e.g., psychology, sociology, behavioral economics) and current research problems and papers; advanced system dynamics models focused on research and practical problems of interest to students; analytic tools and methods for model development, estimation, and analysis (e.g., automating modeling workflow, maximum likelihood, simulated method of moments, dynamical games, dynamic programming); bootcamp for enhancing modeling skills working on multiple problem sets.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"12:00","room":"E62-450"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.879"},{"code":"15.900","title":"Competitive Strategy","level":"G","description":"Explores a wide range of strategic problems, focusing particularly on the sources of competitive advantage and the interaction between industry structure and organizational capabilities. Introduces a wide variety of modern strategy frameworks and methodologies. Builds upon and integrates material from core topics, such as economics and organizational processes. Meets with 15.9001 when offered concurrently. Expectations and evaluation criteria differ for students taking graduate version; consult syllabus or instructor for specific details. Restricted to MIT Sloan master's students in the fall term. No enrollment limitation in the spring term.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"10:00","room":"E51-335"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E51-335"},{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-325"},{"days":["M","W"],"start":"14:30","end":"16:00","room":"E51-325"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.900"},{"code":"15.911","title":"Entrepreneurial Strategy","level":"G","description":"Teaches an integrated strategy framework for start-ups. Provides a deep understanding of the core strategic choices facing innovation-based entrepreneurs, a synthetic framework for the process of choosing and the implementation of entrepreneurial strategy, and the core challenges and approaches for scaling ventures over time. Highlights the process of how to choose an entrepreneurial strategy, the specific choices that matter, how key choices fit together to form an overall entrepreneurial strategy, and the playbook for particular strategies for startups.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-145"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.911"},{"code":"15.C57","title":"Optimization Methods","level":"G","description":"Introduction to the methods and applications of optimization. Topics include linear optimization, duality, non-linear optimization, integer optimization, and optimization under uncertainty. Instruction provided in modeling techniques to address problems arising in practice, mathematical theory to understand the structure of optimization problems, computational algorithms to solve complex optimization problems, and practical applications. Covers several examples and in-depth case studies based on real-world data to showcase impactful applications of optimization across management and engineering. Computational exercises based on the Julia-based programming language JuMP. Includes a term project. Basic competency in computational programming and linear algebra recommended. Students taking graduate version complete additional assignments. This subject was previously listed as 15.093/6.7200/IDS.200. One section primarily reserved for Sloan students; check syllabus for details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-345"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E25-111"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-345"},{"days":["F"],"start":"13:00","end":"14:00","room":"45-230"},{"days":["F"],"start":"14:00","end":"15:00","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.C57"},{"code":"15.C571","title":"Optimization Methods","level":"U","description":"Introduction to the methods and applications of optimization. Topics include linear optimization, duality, non-linear optimization, integer optimization, and optimization under uncertainty. Instruction provided in modeling techniques to address problems arising in practice, mathematical theory to understand the structure of optimization problems, computational algorithms to solve complex optimization problems, and practical applications. Covers several examples and in-depth case studies based on real-world data to showcase impactful applications of optimization across management and engineering. Computational exercises based on the Julia-based programming language JuMP. Includes a term project. Basic competency in computational programming and linear algebra recommended. Students taking graduate version complete additional assignments. This subject was previously listed as 6.7201.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-345"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E25-111"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-345"},{"days":["F"],"start":"13:00","end":"14:00","room":"45-230"},{"days":["F"],"start":"14:00","end":"15:00","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.C571"},{"code":"15.EPE","title":"UPOP Engineering Practice Experience","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.EPE"},{"code":"15.S03","title":"Special Seminar in Management","level":"G","description":"Opportunity for group study by graduate students on current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"16:00","end":"17:30","room":"E51-315"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S03"},{"code":"15.S04","title":"Special Seminar in Management","level":"G","description":"Opportunity for group study by graduate students on current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"10:00","room":"E62-250"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S04"},{"code":"15.S05","title":"Special Seminar in Management","level":"G","description":"Opportunity for group study by graduate students on current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"19:00","room":"45-230"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"4-370"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S05"},{"code":"15.S06","title":"Special Seminar in Management","level":"G","description":"Opportunity for group study by graduate students on current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"16:00","end":"19:00","room":"E62-450"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S06"},{"code":"15.S07","title":"Special Seminar in Management","level":"G","description":"Opportunity for group study by graduate students on current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"19:00","room":"E62-233"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S07"},{"code":"15.S08","title":"Special Seminar in Management","level":"G","description":"Opportunity for group study by graduate students on current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"19:00","room":"E51-145"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S08"},{"code":"15.S09","title":"Special Seminar in Management","level":"G","description":"Opportunity for group study by graduate students on current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"16:00","end":"17:30","room":"E62-223"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S09"},{"code":"15.S10","title":"Special Seminar in Management","level":"G","description":"Opportunity for group study by graduate students on current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"19:00","room":"E62-250"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S10-15.S12"},{"code":"15.S13","title":"Special Seminar in Management","level":"G","description":"Opportunity for group study by graduate students on current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"19:00","room":"34-101"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"34-101"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S13"},{"code":"15.S15","title":"Special Seminar in Management","level":"G","description":"Group study of current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"18:00","end":"21:00","room":"E62-450"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S15"},{"code":"15.S17","title":"Special Seminar in Management","level":"G","description":"Group study of current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"E51-145"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S17"},{"code":"15.S18","title":"Special Seminar in Management","level":"G","description":"Group study of current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"18:00","room":"E62-446"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S18"},{"code":"15.S50","title":"Special Seminar in Management","level":"G","description":"Group study of current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"10:00","room":"E51-372"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E51-372"},{"days":["M","W"],"start":"16:00","end":"17:30","room":"E52-164"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S50"},{"code":"15.S51","title":"Special Seminar in Management","level":"G","description":"Group study of current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"10:00","room":"E62-250"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S51"},{"code":"15.S55","title":"Special Seminar in Management","level":"G","description":"Group study of current topics related to management not otherwise included in curriculum.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"19:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/m15c.html#15.S55"},{"code":"16.00","title":"Introduction to Aerospace and Design","level":"U","description":"Highlights fundamental concepts and practices of aerospace engineering through lectures on aeronautics, astronautics, and the principles of project design and execution. Provides training in the use of Course 16 workshop tools and 3-D printers, and in computational tools, such as CAD. Students engage in teambuilding during an immersive, semester-long project in which teams design, build, and fly radio-controlled lighter-than-air (LTA) vehicles. Emphasizes connections between theory and practice and introduces students to fundamental systems engineering practices, such as oral and written design reviews, performance estimation, and post-flight performance analysis.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:00","room":"33-116"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.00"},{"code":"16.001","title":"Unified Engineering: Materials and Structures","level":"U","description":"Presents fundamental principles and methods of materials and structures for aerospace engineering, and engineering analysis and design concepts applied to aerospace systems.  Topics include statics; analysis of trusses; analysis of statically determinate and indeterminate systems; stress-strain behavior of materials; analysis of beam bending, buckling, and torsion; material and structural failure, including plasticity, fracture, fatigue, and their physical causes. Experiential lab and aerospace system projects provide additional aerospace context.","groups":[{"type":"Lecture","options":[{"days":["M","T","R"],"start":"10:00","end":"11:00","room":"35-225"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"35-225"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.001"},{"code":"16.002","title":"Unified Engineering: Signals and Systems","level":"U","description":"Presents fundamental principles and methods of signals and systems for aerospace engineering, and engineering analysis and design concepts applied to aerospace systems. Topics include linear and time invariant systems; convolution; Fourier and Laplace transform analysis in continuous and discrete time; modulation, filtering, and sampling; and an introduction to feedback control. Experiential lab and system projects provide additional aerospace context. Labs, projects, and assignments involve the use of software such as MATLAB and/or Python.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"35-225"}]},{"type":"Recitation","options":[{"days":["F"],"start":"09:00","end":"10:00","room":"35-225"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.002"},{"code":"16.07","title":"Dynamics","level":"U","description":"Fundamentals of Newtonian mechanics. Kinematics, particle dynamics, motion relative to accelerated reference frames, work and energy, impulse and momentum, systems of particles and rigid body dynamics. Applications to aerospace engineering including introductory topics in orbital mechanics, flight dynamics, inertial navigation and attitude dynamics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"35-225"}]},{"type":"Recitation","options":[{"days":["F"],"start":"15:00","end":"16:00","room":"35-225"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.07"},{"code":"16.09","title":"Statistics and Probability","level":"U","description":"Introduction to statistics and probability with applications to aerospace engineering. Covers essential topics, such as sample space, discrete and continuous random variables, probability distributions, joint and conditional distributions, expectation, transformation of random variables, limit theorems, estimation theory, hypothesis testing, confidence intervals, statistical tests, and regression.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"37-212"}]},{"type":"Recitation","options":[{"days":["R"],"start":"16:00","end":"17:00","room":"37-212"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.09"},{"code":"16.100","title":"Aerodynamics","level":"U","description":"Extends fluid mechanic concepts from Unified Engineering to aerodynamic performance of wings and bodies in sub/supersonic regimes. Addresses themes such as subsonic potential flows, including source/vortex panel methods; viscous flows, including laminar and turbulent boundary layers; aerodynamics of airfoils and wings, including thin airfoil theory, lifting line theory, and panel method/interacting boundary layer methods; and supersonic and hypersonic airfoil theory. Material may vary from year to year depending upon focus of design problem.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"24-115"}]},{"type":"Lab","options":[{"days":["F"],"start":"11:00","end":"13:00","room":"3-370"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.100"},{"code":"16.110","title":"Flight Vehicle Aerodynamics","level":"G","description":"Aerodynamic flow modeling and representation techniques. Potential farfield approximations. Airfoil and lifting-surface theory. Laminar and turbulent boundary layers and their effects on aerodynamic flows. Nearfield and farfield force analysis. Subsonic, transonic, and supersonic compressible flows. Experimental methods and measurement techniques. Aerodynamic models for flight dynamics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"33-319"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.110"},{"code":"16.215","title":"Topology Optimization of Structures","level":"G","description":"Covers free-form topology design of structures using formal optimization methods and mathematical programs, including design of structural systems, mechanisms, and material architectures. Strong emphasis on designing with gradient-based optimizers, finite element methods, and design problems governed by structural mechanics. Incorporates optimization theory and computational mechanics fundamentals, problem formulation, sensitivity analysis; and introduces cutting-edge extensions, including to other and multiple physics.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"1-273"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.215"},{"code":"16.221","title":"Structural Dynamics","level":"G","description":"Examines response of structures to dynamic excitation: free vibration, harmonic loads, pulses and earthquakes. Covers systems of single- and multiple-degree-of-freedom, up to the continuum limit, by exact and approximate methods. Includes applications to buildings, ships, aircraft and offshore structures. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.221"},{"code":"16.30","title":"Feedback Control Systems","level":"U","description":"Studies state-space representation of dynamic systems, including model realizations, controllability, and observability. Introduces the state-space approach to multi-input-multi-output control system analysis and synthesis, including full state feedback using pole placement, linear quadratic regulator, stochastic state estimation, and the design of dynamic control laws. Also covers performance limitations and robustness. Extensive use of computer-aided control design tools. Applications to various aerospace systems, including navigation, guidance, and control of vehicles. Laboratory exercises utilize a palm-size drone. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"32-144"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"33-419"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.30"},{"code":"16.31","title":"Feedback Control Systems","level":"G","description":"Graduate-level version of 16.30; see description under 16.30. Includes additional homework questions, laboratory experiments, and a term project beyond 16.30 with a particular focus on the material associated with state-space realizations of MIMO transfer function (matrices); MIMO zeros, controllability, and observability; stochastic processes and estimation; limitations on performance; design and analysis of dynamic output feedback controllers; and robustness of multivariable control systems.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"32-144"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.31"},{"code":"16.391","title":"Statistics for Engineers and Scientists","level":"G","description":"Rigorous introduction to fundamentals of statistics motivated by engineering applications. Topics include exponential families, order statistics, sufficient statistics, estimation theory, hypothesis testing, measures of performance, notions of optimality, analysis of variance (ANOVA), simple linear regression, and selected topics.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"26-328"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.391"},{"code":"16.400","title":"Human Systems Engineering","level":"U","description":"Provides a fundamental understanding of human factors that must be taken into account in the design and engineering of complex aviation, space, and medical systems. Focuses primarily on derivation of human engineering design criteria from sensory, motor, and cognitive sources. Includes principles of displays, controls and ergonomics, manual control, the nature of human error, basic experimental design, and human-computer interaction in supervisory control settings. Students taking graduate version complete a research project with a final written report and oral presentation.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"3-370"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.400"},{"code":"16.410","title":"Principles of Autonomy and Decision Making","level":"U","description":"Surveys decision making methods used to create highly autonomous systems and decision aids. Applies models, principles and algorithms taken from artificial intelligence and operations research. Focuses on planning as state-space search, including uninformed, informed and sampling-based search, activity and motion planning, probabilistic and adversarial planning, Markov models and decision processes, Bayesian filtering, reinforcement learning, and machine learning. Includes methods for satisfiability and optimization of logical and finite domain constraints, graphical models, and methods for search, inference, and conflict-learning. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-163"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"33-319"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.410"},{"code":"16.413","title":"Principles of Autonomy and Decision Making","level":"G","description":"Surveys decision making methods used to create highly autonomous systems and decision aids. Applies models, principles and algorithms taken from artificial intelligence and operations research. Focuses on planning as state-space search, including uninformed, informed and sampling-based search, activity and motion planning, probabilistic and adversarial planning, Markov models and decision processes, Bayesian filtering, reinforcement learning, and machine learning. Includes methods for satisfiability and optimization of logical and finite domain constraints, graphical models, and methods for search, inference, and conflict-learning. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.413"},{"code":"16.420","title":"Planning Under Uncertainty","level":"G","description":"Concepts, principles, and methods for planning with imperfect knowledge. Topics include state estimation, planning in information space, partially observable Markov decision processes, reinforcement learning and planning with uncertain models. Students will develop an understanding of how different planning algorithms and solutions techniques are useful in different problem domains. Previous coursework in artificial intelligence and state estimation strongly recommended.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"3-133"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.420"},{"code":"16.422","title":"Human Supervisory Control of Automated Systems","level":"G","description":"Principles of supervisory control and telerobotics. Different levels of automation are discussed, as well as the allocation of roles and authority between humans and machines. Human-vehicle interface design in highly automated systems. Decision aiding. Trade-offs between human control and human monitoring. Automated alerting systems and human intervention in automatic operation. Enhanced human interface technologies such as virtual presence. Performance, optimization, and social implications of the human-automation system. Examples from aerospace, ground, and undersea vehicles, robotics, and industrial systems.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"33-418"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.422"},{"code":"16.426","title":"Quantitative and Clinical Physiology","level":"G","description":"Application of the principles of energy and mass flow to major human organ systems. Anatomical, physiological and clinical features of the cardiovascular, respiratory and renal systems. Mechanisms of regulation and homeostasis. Systems, features and devices that are most illuminated by the methods of physical sciences and engineering models. Required laboratory work includes animal studies. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-265"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:00","end":"14:00","room":"34-301"},{"days":["W"],"start":"14:00","end":"15:00","room":"34-301"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.426"},{"code":"16.453","title":"Human Systems Engineering","level":"G","description":"Provides a fundamental understanding of human factors that must be taken into account in the design and engineering of complex aviation, space, and medical systems. Focuses primarily on derivation of human engineering design criteria from sensory, motor, and cognitive sources. Includes principles of displays, controls and ergonomics, manual control, the nature of human error, basic experimental design, and human-computer interaction in supervisory control settings. Students taking graduate version complete a research project with a final written report and oral presentation.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"3-370"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.453"},{"code":"16.459","title":"Bioengineering Journal Article Seminar","level":"G","description":"Each term, the class selects a new set of professional journal articles on bioengineering topics of current research interest. Some papers are chosen because of particular content, others are selected because they illustrate important points of methodology. Each week, one student leads the discussion, evaluating the strengths, weaknesses, and importance of each paper. Subject may be repeated for credit a maximum of four terms. Letter grade given in the last term applies to all accumulated units of 16.459.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"31-270"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.459"},{"code":"16.511","title":"Aircraft Engines and Gas Turbines","level":"G","description":"Performance and characteristics of aircraft jet engines and industrial gas turbines, as determined by thermodynamic and fluid mechanic behavior of engine components: inlets, compressors, combustors, turbines, and nozzles. Discusses various engine types, including advanced turbofan configurations, limitations imposed by material properties and stresses. Emphasizes future design trends including reduction of noise, pollutant formation, fuel consumption, and weight.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"33-319"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.511"},{"code":"16.55","title":"Ionized Gases","level":"G","description":"Properties and behavior of low-temperature plasmas for energy conversion, plasma propulsion, and gas lasers. Equilibrium of ionized gases: energy states, statistical mechanics, and relationship to thermodynamics. Kinetic theory: motion of charged particles, distribution function, collisions, characteristic lengths and times, cross sections, and transport properties. Gas surface interactions: thermionic emission, sheaths, and probe theory. Radiation in plasmas and diagnostics.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"33-319"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.55"},{"code":"16.63","title":"System Safety","level":"U","description":"Introduces the concepts of system safety and how to analyze and design safer systems. Topics include the causes of accidents in general, and recent major accidents in particular; hazard analysis, safety-driven design techniques; design of human-automation interaction; integrating safety into the system engineering process; and managing and operating safety-critical systems.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"12:00","room":"32-141"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.63"},{"code":"16.632A","title":"Introduction to Autonomous Machines I","level":"U","description":"Provides an introduction to the fundamental aspects of autonomous navigation, which includes a series of lab exercises that encompass a variety of sensors attached to a small autonomous vehicle. Presents how to properly acquire sensor data, use sensor data for robotic applications, and structure their computer programs to optimize the utilization of sensor data. Students should have concurrent or prior programming experience. Required for students in the NEET Autonomous Machine thread and open to other students when available space exists.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"33-418"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.632A"},{"code":"16.633","title":"NEET Junior Seminar: Autonomous Machines","level":"U","description":"Provides instruction in applying and implementing the fundamental concepts of machine learning with an autonomous vehicle equipped with a variety of sensors. Topics include: neural network architecture, training and optimization, activation functions, loss functions, fitting models, gradients, and initialization as utilized in real-world implementation of machine learning for autonomous vehicle navigation. Limited to students in the NEET Autonomous Machines thread.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"16:00","end":"17:00","room":"35-310"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.633"},{"code":"16.634","title":"NEET Senior Seminar: Autonomous Machines","level":"U","description":"Senior project subject for the NEET Autonomous Machines thread. Provides students the opportunity to apply their skills, knowledge, and conceptual understanding of robotics and autonomous systems to develop a functional working project that involves aspects of design, control, simulation, perception, algorithm implementation, and hardware and software integration. Working in small teams, students develop their projects from concept to completion. Limited to students in the NEET Autonomous Machines thread or with instructor's permission.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"12:00","end":"13:30","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.634"},{"code":"16.64","title":"Flight Measurement Laboratory","level":"U","description":"Opportunity to see aeronautical theory applied in real-world environment of flight. Students assist in design and execution of simple engineering flight experiments in light aircraft. Typical investigations include determination of stability derivatives, verification of performance specifications, and measurement of navigation system characteristics. Restricted to students in Aeronautics and Astronautics.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"17:00","room":"33-422"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.64"},{"code":"16.65","title":"Remote Sensing: Physical Principles and Techniques","level":"U","description":"Introduction to the physics of remote sensing, with applications to the study of Earth, the Moon, and other planets and solar system bodies, as well as to emerging industrial applications. Covers the physical principles of optical, thermal, radar, and lidar remote sensing with an emphasis on the fundamental properties of electromagnetic waves; the principles of electromagnetic scattering from real and idealized materials, including various types of surfaces and vegetation; the interaction of electromagnetic radiation with the atmosphere; and thermal and microwave emission from various media. Discusses remote sensing platforms along with the essentials of orbital mechanics and data processing methods and tools. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"54-911"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.65"},{"code":"16.650","title":"Engineering Leadership Lab","level":"U","description":"Develops leadership, teamwork and communication skills by exposing students to leadership frameworks, models, and cases within engineering contexts in an interactive, practice-based environment. Students are members of and lead teams, participate in guided reflections on individual and team successes, and discover opportunities for improvement in controlled settings. Experiential learning model includes design-implement activities, role-play simulations, small group activities and discussions, and performance and peer assessments by and of other students, with frequent engineering industry-guest participation. Content is frequently student-driven. First-year Gordon Engineering Leadership Program (GEL) students register for 6.9110. Second-year GEL Program students register for 6.9130. Preference to students enrolled in the Bernard M. Gordon-MIT Engineering Leadership Program.","groups":[{"type":"Lab","options":[{"days":["F"],"start":"09:00","end":"11:00","room":"32-124"},{"days":["F"],"start":"13:00","end":"15:00","room":"32-124"},{"days":["F"],"start":"15:00","end":"17:00","room":"32-124"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.650"},{"code":"16.651","title":"Engineering Leadership","level":"U","description":"Exposes students to the models and methods of engineering leadership within the contexts of conceiving, designing, implementing and operating products, processes and systems. Introduces the Capabilities of Effective Engineering Leaders, and models and theories related to the capabilities. Discusses the appropriate times and reasons to use particular models to deliver engineering success. Includes occasional guest speakers or panel discussions. May be repeated for credit once with permission of instructor. Preference to first-year students in the Gordon Engineering Leadership Program.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:00","end":"12:30","room":"4-153"},{"days":["M"],"start":"13:00","end":"14:30","room":"4-153"},{"days":["T"],"start":"11:00","end":"12:30","room":"4-153"},{"days":["T"],"start":"13:00","end":"14:30","room":"4-153"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.651"},{"code":"16.653","title":"Management in Engineering","level":"U","description":"Introduction and overview of engineering management. Financial principles, management of innovation, technical strategy and best management practices. Case study method of instruction emphasizes participation in class discussion. Focus is on the development of individual skills and management tools. Restricted to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"35-225"}]},{"type":"Lab","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"1-150"},{"days":["T"],"start":"10:00","end":"11:00","room":"1-375"},{"days":["R"],"start":"16:00","end":"17:00","room":"1-375"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-135"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.653"},{"code":"16.662","title":"Design Thinking and Innovation Leadership for Engineers","level":"U","description":"Project-based course develops students' ability to conceive, implement, and evaluate successful projects in any engineering discipline. Lessons focus on an iterative design process, techniques for leading the creative process in teams, the ethics of engineering systems, methods for articulating designs with group collaboration, identifying and reconciling paradoxes of engineering designs, using a systems thinking approach for stakeholder analysis, and communicating solution concepts with impact. Working in teams, students employ design thinking techniques and leadership skills to collaboratively conceive, implement, and iteratively refine through user feedback robust applications using a simple web-based platform. Students also give oral presentations and receive feedback to sharpen their communication skills.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"VIRTUAL"}]},{"type":"Design","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"VIRTUAL"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.662"},{"code":"16.6621","title":"Introduction to Design Thinking and Innovation in Engineering","level":"U","description":"Introduces students to concepts of design thinking and innovation that can be applied to any engineering discipline. Focuses on introducing an iterative design process, a systems-thinking approach for stakeholder analysis, methods for articulating design concepts, methods for concept selection, and techniques for testing with users. Provides an opportunity for first-year students to explore product or system design and development, and to build their understanding of what it means to lead and coordinate projects in engineering design. Subject can count toward the 6-unit discovery-focused credit limit for first-year students. Enrollment limited to 25; priority to first-year students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"32-123"},{"days":["W"],"start":"12:00","end":"13:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.6621"},{"code":"16.662A","title":"Design Thinking and Innovation Leadership for Engineers","level":"U","description":"Introductory subject in design thinking and innovation. Develops students' ability to conceive, implement, and evaluate successful projects in any engineering discipline. Lessons focus on an iterative design process, a systems-thinking approach for stakeholder analysis, methods for articulating design concepts, methods for concept selection, and techniques for testing with users.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"32-141"},{"days":["M"],"start":"15:00","end":"17:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"32-123"},{"days":["W"],"start":"12:00","end":"13:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.662A"},{"code":"16.662B","title":"Design Thinking and Innovation Project","level":"U","description":"Project-based subject. Students employ design-thinking techniques learned in 6.902A to develop a robust speech-recognition application using a web-based platform. Students practice in leadership and teamwork skills as they collaboratively conceive, implement, and iteratively refine their designs based on user feedback. Topics covered include techniques for leading the creative process in teams, the ethics of engineering systems, methods for articulating designs with group collaboration, identifying and reconciling paradoxes of engineering designs, and communicating solution concepts with impact. Students present oral presentations and receive feedback to sharpen their communication skills.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"32-141"},{"days":["M"],"start":"15:00","end":"17:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"32-123"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.662B"},{"code":"16.667","title":"Engineering Leadership Lab","level":"U","description":"Advances students' leadership, teamwork, and communication skills through further exposure to leadership frameworks, models, and cases within an engineering context in an interactive, practice-based environment. Students coach others, assess performance, and lead guided reflections on individual and team successes, while discovering opportunities for improvement. Students assist with programmatic planning and implementation of role-play simulations, small group discussions, and performance and peer assessments by and of other students and by instructors. Includes frequent engineering industry-guest participation and involvement. Content is frequently student-led. Second year Gordon Engineering Leadership Program (GEL) Program students register for 6.9130. Preference to students enrolled in the second year of the Gordon-MIT Engineering Leadership Program.","groups":[{"type":"Lab","options":[{"days":["F"],"start":"09:00","end":"11:00","room":"32-124"},{"days":["F"],"start":"13:00","end":"15:00","room":"32-124"},{"days":["F"],"start":"15:00","end":"17:00","room":"32-124"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.667"},{"code":"16.676","title":"Ethics for Engineers","level":"U","description":"Explores how to be an ethical engineer. Students examine engineering case studies alongside key readings by foundational ethical thinkers from Aristotle to Martin Luther King, Jr., and investigate which ethical approaches are best and how to apply them. Topics include justice, rights, cost-benefit analysis, safety, bias, genetic engineering, climate change, and the promise and peril of AI. Discussion-based, with the aim of introducing students to new ways of thinking. All sections cover the same core ethical frameworks, but some sections have a particular focus for case studies, such as bioengineering, or have an in-depth emphasis on particular thinkers. The subject is taught in separate sections. Students are eligible to take any section regardless of their registered subject number. For 20.005, students additionally undertake an ethical-technical analysis of a BE-related topic of their choosing.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["T"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"19:00","end":"21:00","room":"66-148"},{"days":["R"],"start":"15:00","end":"17:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.676"},{"code":"16.677","title":"Designing Virtual Worlds","level":"U","description":"Three primary areas of focus are: creating new Virtual Reality experiences; mapping the state of emerging tools; and hosting guests ? leaders in the VR/XR community, who serve as coaches for projects. Students have significant leeway to customize their own learning environment. As the field is rapidly evolving, each semester focuses on a new aspect of virtual worlds, based on the current state of innovations. Students work in teams of interdisciplinary peers from Berklee College of Music and Harvard University. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:30","end":"16:30","room":"3-370"}]},{"type":"Recitation","options":[{"days":["T"],"start":"19:00","end":"20:00","room":"9-152"},{"days":["W"],"start":"19:00","end":"20:00","room":"9-152"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.677"},{"code":"16.678","title":"Designing Virtual Worlds","level":"G","description":"Three primary areas of focus are: creating new Virtual Reality experiences; mapping the state of emerging tools; and hosting guests ? leaders in the VR/XR community, who serve as coaches for projects. Students have significant leeway to customize their own learning environment. As the field is rapidly evolving, each semester focuses on a new aspect of virtual worlds, based on the current state of innovations. Students work in teams of interdisciplinary peers from Berklee College of Music and Harvard University. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:30","end":"16:30","room":"3-370"}]},{"type":"Recitation","options":[{"days":["T"],"start":"19:00","end":"20:00","room":"9-152"},{"days":["W"],"start":"19:00","end":"20:00","room":"9-152"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.678"},{"code":"16.69","title":"People and the Planet: Environmental Governance and Science","level":"U","description":"Introduces governance and science aspects of complex environmental problems and approaches to solutions. Introduces quantitative analyses and methodological tools to analyze environmental issues that have human and natural components. Demonstrates concepts through a series of in-depth case studies of environmental governance and science problems. Students develop writing, quantitative modeling, and analytical skills in assessing environmental systems problems and developing solutions. Through experiential activities, such as modeling and policy exercises, students engage with the challenges and possibilities of governance in complex, interacting systems, including biogeophysical processes and societal and stakeholder interactions.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:30","end":"12:30","room":"54-820"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.69"},{"code":"16.71","title":"The Airline Industry","level":"G","description":"Overview of the global airline industry and its economic and operational foundations. Examines interactions among key stakeholders in the aviation system, including airlines, airports, and air traffic management. Introduces fundamentals of airline economics, including demand, cost structures, pricing, competition, and regulatory frameworks. Covers operational and strategic decision-making such as fleet and network planning and airline operations. Considers system-level challenges including safety, environmental sustainability, and evolving global market dynamics. Students analyze industry performance, market developments, and emerging operational challenges in aviation.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.71"},{"code":"16.72","title":"Air Traffic Control","level":"G","description":"Introduces the various aspects of present and future Air Traffic Control systems. Descriptions of the present system: systems-analysis approach to problems of capacity and safety; surveillance, including NAS and ARTS; navigation subsystem technology; aircraft guidance and control; communications; collision avoidance systems; sequencing and spacing in terminal areas; future directions and development; critical discussion of past proposals and of probable future problem areas. Requires term paper.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"33-319"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.72"},{"code":"16.821","title":"Flight Vehicle Development","level":"U","description":"Focuses on implementation and operation of a flight system. Emphasizes system integration, implementation, and performance verification using methods of experimental inquiry, and addresses principles of laboratory safety. Students refine subsystem designs and fabricate working prototypes. Includes component integration into the full system with detailed analysis and operation of the complete vehicle in the laboratory and in the field, as well as experimental analysis of subsystem performance, comparison with physical models of performance and design goals, and formal review of the overall system design. Knowledge of the engineering design process is helpful. Provides instruction in written and oral communication.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:00","room":"33-419"}]},{"type":"Lab","options":[{"days":["M","W"],"start":"15:00","end":"17:00","room":"33-419"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.821"},{"code":"16.83","title":"Space Systems Engineering","level":"U","description":"Design of a complete space system, including systems analysis, trajectory analysis, entry dynamics, propulsion and power systems, structural design, avionics, thermal and environmental control, human factors, support systems, and weight and cost estimates. Students participate in teams, each responsible for an integrated vehicle design, providing experience in project organization and interaction between disciplines. Includes several aspects of team communication including three formal presentations, informal progress reports, colleague assessments, and written reports. Course 16 students are expected to complete two professional or concentration subjects from the departmental program before taking this capstone. Offered alternate fall and spring terms.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"33-218"}]},{"type":"Lab","options":[{"days":["T","R"],"start":"16:00","end":"17:00","room":"33-218"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.83"},{"code":"16.842","title":"Fundamentals of Systems Engineering","level":"G","description":"General introduction to systems engineering for aerospace and more general electro-mechanical-cyber systems. Built on the V-model as well as an agile approach. Topics include stakeholder analysis, requirements definition, system architecture and concept generation, trade-space exploration and concept selection, design definition and optimization, system integration and interface management, system safety, verification and validation, and commissioning and operations. Discusses the trade-offs between performance, life-cycle cost and system operability. Readings based on systems engineering standards. Individual homework assignments apply concepts from class. Prepares students for the systems field exam in the Department of Aeronautics and Astronautics.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"11:00","end":"13:00","room":"33-218"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.842"},{"code":"16.850","title":"Remote Sensing: Physical Principles and Techniques","level":"G","description":"Introduction to the physics of remote sensing, with applications to the study of Earth, the Moon, and other planets and solar system bodies, as well as to emerging industrial applications. Covers the physical principles of optical, thermal, radar, and lidar remote sensing with an emphasis on the fundamental properties of electromagnetic waves; the principles of electromagnetic scattering from real and idealized materials, including various types of surfaces and vegetation; the interaction of electromagnetic radiation with the atmosphere; and thermal and microwave emission from various media. Discusses remote sensing platforms along with the essentials of orbital mechanics and data processing methods and tools. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"54-911"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.850"},{"code":"16.851","title":"Introduction to Satellite Engineering","level":"G","description":"Covers the principles and governing equations fundamental to the design, launch, and operation of artificial satellites in Earth's orbit and beyond. Material includes the vis-viva equation; the rocket equation; basic orbital maneuvers, including Hohmann transfers; bielliptic trajectories, as well as spiral transfers; the link budget equation; spacecraft power and propulsion; thermal equilibrium and interactions of spacecraft with the space environment, such as aerodynamic drag; electrostatic charging; radiation; and meteorids. Spacecraft are initially treated parametrically as point masses and then as rigid bodies subject to Euler's equations of rotational motion. Serves as a prerequisite for more advanced material in satellite engineering, including the technological implementation of various subsystems. Lectures are offered in a hybrid format, in person and remote.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"3-370"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.851"},{"code":"16.853","title":"Advanced Satellite Engineering","level":"G","description":"Advanced material in satellite engineering, including the physical implementation of spacecraft hardware and software in payloads and bus subsystems, including structures, attitude determination and control, electrical power systems (EPS), control and data handling (CDH), guidance navigation and control (GNC), thermal management, communications, and others. Examples of spacecraft technologies and design tradeoffs are highlighted based on past, current, and future missions. Emphasis on mission success and identification and preventation of spacecraft and mission failures modes. Prepares students for the design of Earth observation as well as interplanetary science missions. Advanced assignments require computational skills in Matlab or Python and short presentations. Guest speakers from NASA and industry. Serves as a basis for the field examination in space systems.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"3-370"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.853"},{"code":"16.857","title":"Asking How Space Enabled Designs Advance Justice and Development","level":"G","description":"Examines theoretical and practical challenges of applying complex technology, such as space systems, to advance justice and development within human society. Proposes and critiques a concept of justice and development based on attainment of the US Sustainable Development Goals. Analyzes text by historians and economists around global patterns of uneven technology access. Teaches systems engineering tools to analyze the context, stakeholders, functions and forms of complex systems that impact society. Presents six space technologies used for specific Sustainable Development Goal. Students read several text, discuss key themes, write reflective responses, and write a research proposal on a topic of their choice. Part of two-class series on space technology and sustainable development. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"09:00","end":"12:00","room":"E14-493"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.857"},{"code":"16.861","title":"System Design and Management for a Changing World: Combined","level":"G","description":"Practical-oriented subject that builds upon theory and methods and culminates in extended application. Covers methods to identify, value, and implement flexibility in design (real options). Topics include definition of uncertainties, simulation of performance for scenarios, screening models to identify desirable flexibility, decision analysis, and multidimensional economic evaluation. Students demonstrate proficiency through an extended application to a system design of their choice. Complements research or thesis projects. Class is 'flipped' to maximize student engagement and learning. Meets with IDS.333 in the first half of term. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.861"},{"code":"16.863","title":"System Safety Concepts","level":"G","description":"Covers important concepts and techniques in designing and operating safety-critical systems. Topics include the nature of risk, formal accident and human error models, causes of accidents, fundamental concepts of system safety engineering, system and software hazard analysis, designing for safety, fault tolerance, safety issues in the design of human-machine interaction, verification of safety, creating a safety culture, and management of safety-critical projects. Includes a class project involving the high-level system design and analysis of a safety-critical system. Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"12:00","room":"32-141"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.863"},{"code":"16.88","title":"Prototyping our Sci-Fi Space Future: Designing & Deploying Projects for Zero Gravity Flights","level":"G","description":"Instruction in project development, prototyping, and deployment readiness for parabolic flights. Admitted student teams are offered flyer and project-deployment slots on the Space Exploration Initiative's spring parabolic flight, upon successful completion of the course in the fall and integration with the flight provider. Covers three main topic areas: 1) rapid prototyping and engineering skills to prepare projects for operation in microgravity; 2) logistics, training, and safety pre-approval steps to meet flight readiness requirements and pass a Technical Readiness Review (TRR); and 3) creative and technical lenses for the future of space exploration, examining the MIT Space Exploration Initiative's design and prototyping approach, and MIT parabolic flight research examples across Science, Engineering, Art, and Design, and across departments. Enrollment limited; admission by application.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"33-218"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.88"},{"code":"16.880","title":"Applied Category Theory for Engineering Design","level":"G","description":"Considers the multiple trade-offs at various abstraction levels and scales when designing complex, multi-component systems. Covers topics from foundational principles to advanced applications, emphasizing the role of compositional thinking in engineering. Introduces category theory as a mathematical framework for abstraction and composition, enabling a unified and modular approach to modeling, analyzing, and designing interconnected systems. Showcases successful applications in areas such as dynamical systems and automated system design optimization, with a focus on autonomous robotics and mobility. Offers students the opportunity to work on their own application through a dedicated project in the second half of the term. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"5-234"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.880"},{"code":"16.886","title":"Air Transportation Systems Architecting","level":"G","description":"Addresses the architecting of air transportation systems.  Focuses on the conceptual phase of product definition including  technical, economic, market, environmental, regulatory, legal,  manufacturing, and societal factors. Centers on a realistic  system case study and includes a number of lectures from industry  and government. Past examples include the Very Large Transport  Aircraft, a Supersonic Business Jet and a Next Generation Cargo  System. Identifies the critical system level issues and  analyzes them in depth via student team projects and individual  assignments. Overall goal is to produce a  business plan and a system specifications document that can be used  to assess candidate systems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"33-319"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.886"},{"code":"16.910","title":"Introduction to Modeling and Simulation","level":"G","description":"Introduction to computational techniques for modeling and simulation of a variety of large and complex engineering, science, and socio-economical systems. Prepares students for practical use and development of computational engineering in their own research and future work. Topics include mathematical formulations (e.g., automatic assembly of constitutive and conservation principles); linear system solvers (sparse and iterative); nonlinear solvers (Newton and homotopy); ordinary, time-periodic and partial differential equation solvers; and model order reduction. Students develop their own models and simulators for self-proposed applications, with an emphasis on creativity, teamwork, and communication. Prior basic linear algebra required and at least one numerical programming language (e.g., MATLAB, Julia, Python, etc.) helpful.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.910"},{"code":"16.920","title":"Numerical Methods for Partial Differential Equations","level":"G","description":"Covers the fundamentals of modern numerical techniques for a wide range of linear and nonlinear elliptic, parabolic, and hyperbolic partial differential and integral equations. Topics include mathematical formulations; finite difference, finite volume, finite element, and boundary element discretization methods; and direct and iterative solution techniques. The methodologies described form the foundation for computational approaches to engineering systems involving heat transfer, solid mechanics, fluid dynamics, and electromagnetics. Computer assignments requiring programming.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"37-212"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.920"},{"code":"16.940","title":"Numerical Methods for Stochastic Modeling and Inference","level":"G","description":"Advanced introduction to numerical methods for treating uncertainty in computational simulation. Draws examples from a range of engineering and science applications, emphasizing systems governed by ordinary and partial differential equations. Uncertainty propagation and assessment: Monte Carlo methods, variance reduction, sensitivity analysis, adjoint methods, polynomial chaos and Karhunen-Loève expansions, and stochastic Galerkin and collocation methods. Interaction of models with observational data, from the perspective of statistical inference: Bayesian parameter estimation, statistical regularization, Markov chain Monte Carlo, sequential data assimilation and filtering, and model selection.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"32-124"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.940"},{"code":"16.985","title":"Global Operations Leadership Seminar","level":"G","description":"Integrative forum in which worldwide leaders in business, finance, government, sports, and education share their experiences and insights with students aspiring to run global operations. Students play a large role in managing the seminar. Preference to LGO students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"18:00","room":"E51-335"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.985"},{"code":"16.987","title":"First-Year Graduate Student Seminar","level":"G","description":"Features presentations and discussions with faculty, staff, and students, covering key topics essential for success at MIT. These include: graduate registration; advisor-advisee expectations; academic and research milestones; thesis development; funding options; applying for fellowships; professional development; publishing in conferences and journal; procurement and reimbursement; computing and software resources; summer internships; working with UROPs or visiting researchers; conflict resolution; outreach; recruiting; export control; nonresident status; graduation logistics; and strategies for managing implicit bias, as well as maintaining mental and physical health.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:30","end":"13:00","room":"37-252"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.987"},{"code":"16.990","title":"Leading Creative Teams","level":"G","description":"Prepares students to lead teams charged with developing creative solutions in engineering and technical environments. Grounded in research but practical in focus, equips students with leadership competencies such as building self-awareness, motivating and developing others, creative problem solving, influencing without authority, managing conflict, and communicating effectively. Teamwork skills include how to convene, launch, and develop various types of teams, including project teams. Learning methods emphasize personalized and experiential skill development. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.990"},{"code":"16.995","title":"Doctoral Research and Communication Seminar","level":"G","description":"Presents fundamental concepts of technical communication. Addresses how to articulate a research problem, as well as the communication skills necessary to reach different audiences. The primary focus is on technical presentations, but includes aspects of written communication. Students give two technical talks during the term, and provide oral and written feedback to each other.  Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"10:00","end":"12:00","room":"33-419"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.995"},{"code":"16.C20","title":"Introduction to Computational Science and Engineering","level":"U","description":"Provides an introduction to computational algorithms used throughout engineering and science (natural and social) to simulate time-dependent phenomena; optimize and control systems; and quantify uncertainty in problems involving randomness, including an introduction to probability and statistics. Combination of 6.100A and 16.C20J counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"3-370"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.C20"},{"code":"16.C25","title":"Real World Computation with Julia","level":"U","description":"Focuses on algorithms and techniques for writing and using modern technical software in a job, lab, or research group environment that may consist of interdisciplinary teams, where performance may be critical, and where the software needs to be flexible and adaptable. Topics include automatic differentiation, matrix calculus, scientific machine learning, parallel and GPU computing, and performance optimization with introductory applications to climate science, economics, agent-based modeling, and other areas. Labs and projects focus on performant, readable, composable algorithms, and software. Programming will be in Julia. Expects students to have some familiarity with Python, Matlab, or R. No Julia experience necessary.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.C25"},{"code":"16.EPE","title":"UPOP Engineering Practice Experience","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m16a.html#16.EPE"},{"code":"16.S199","title":"Advanced Special Subject in Mechanics and Physics of Fluids","level":"G","description":"Organized lecture or laboratory subject consisting of material not available in regularly scheduled fluids subjects. Prior approval required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"33-319"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.S199"},{"code":"16.S399","title":"Advanced Special Subject in Information and Control","level":"G","description":"Organized lecture or laboratory subject consisting of material not available in regularly scheduled subjects. Prior approval required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"33-418"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.S399"},{"code":"16.S893","title":"Advanced Special Subject in Aerospace Systems","level":"G","description":"Organized lecture or laboratory subject consisting of material not available in regularly scheduled subjects. Prior approval required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"33-218"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.S893"},{"code":"16.S896","title":"Advanced Special Subject in Aerospace Systems","level":"G","description":"Organized lecture or laboratory subject consisting of material not available in regularly scheduled subjects. Prior approval required.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"15:00","end":"17:00","room":"33-218"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.S896"},{"code":"16.S983","title":"Advanced Special Subject","level":"G","description":"Organized lecture or laboratory subject consisting of material not available in regularly scheduled subjects. Prior approval required.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:00","room":"33-319"}]}],"url":"http://student.mit.edu/catalog/m16b.html#16.S983"},{"code":"17.000","title":"Political Philosophy","level":"G","description":"Systematic examination of selected issues in political philosophy. Topic changes each year and subject may be taken repeatedly with permission of instructor.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"10:00","end":"12:00","room":"E53-485"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.000"},{"code":"17.006","title":"Feminist Thought","level":"G","description":"Analyzes theories of gender and politics, especially ideologies of gender and their construction; definitions of public and private spheres; gender issues in citizenship, the development of the welfare state, experiences of war and revolution, class formation, and the politics of sexuality. Graduate students are expected to pursue the subject in greater depth through reading and individual research.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.006"},{"code":"17.007","title":"Feminist Thought","level":"U","description":"Analyzes theories of gender and politics, especially ideologies of gender and their construction; definitions of public and private spheres; gender issues in citizenship, the development of the welfare state, experiences of war and revolution, class formation, and the politics of sexuality. Graduate students are expected to pursue the subject in greater depth through reading and individual research.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.007"},{"code":"17.01","title":"Justice","level":"U","description":"Provides an introduction to contemporary political thought centered around the ideal of justice and the realities of injustice. Examines what a just society might look like and how we should understand various forms of oppression and domination. Studies three theories of justice (utilitarianism, libertarianism, and egalitarian liberalism) and brings them into conversation with other traditions of political thought (critical theory, communitarianism, republicanism, and post-structuralism). Readings cover foundational debates about equality, freedom, recognition, and power.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"15:00","end":"17:00","room":"48-316"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"56-167"},{"days":["F"],"start":"11:00","end":"12:00","room":"56-167"},{"days":["F"],"start":"12:00","end":"13:00","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.01"},{"code":"17.031","title":"American Political Thought","level":"U","description":"Examines political thought from the American colonial period through the 20th century. Considers the influences that gave rise to American political ideas and the implication of those ideas in a modern context, with particular emphasis on issues of liberty, equality, and the role of values from a liberal democratic lens.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"26-142"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.031"},{"code":"17.100","title":"Field Seminar in Political Economy","level":"G","description":"Examines broad range of topics — such as social classes, states, interest groups, inequality welfare states, comparative capitalism, race, and gender — from both classical (Marx and Weber) and contemporary theorists. Limited to 12; preference to Course 17 PhD students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:00","end":"13:00","room":"E53-485"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.100"},{"code":"17.20","title":"Introduction to the American Political Process","level":"U","description":"Provides a substantive overview of US politics and an introduction to the discipline of political science. Surveys the institutional foundations of US politics as well as the activities of political elites, organizations, and ordinary citizens. Explores the application of general political science concepts and analytic frameworks to specific episodes and phenomena in US politics. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"66-160"}]},{"type":"Recitation","options":[{"days":["M"],"start":"15:00","end":"16:00","room":"56-167"},{"days":["M"],"start":"16:00","end":"17:00","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.20"},{"code":"17.200","title":"American Political Behavior I","level":"G","description":"Analyzes mass political behavior within the American political system. Examines political ideology, party identification, public opinion, voting behavior, media effects, racial attitudes, mass-elite relations, and opinion-policy linkages. Surveys and critiques the major theoretical approaches and empirical research in the field of political behavior.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:00","end":"11:00","room":"E53-485"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.200"},{"code":"17.263","title":"Electoral Politics, Public Opinion, and Democracy","level":"U","description":"Considers the role of elections in American politics. Issues explored include empirical and theoretical models of electoral competition, the effect of elections on public policy, and proposals to improve elections. Special emphasis is given to mass voting behavior, political parties, the media, and campaign finance. Subject focuses on US elections, but provides some contrasts with other countries, especially the United Kingdom.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"2-135"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.263"},{"code":"17.276","title":"Public Opinion Research Training Lab","level":"G","description":"Offers practical training in public opinion research and provides students with an opportunity to conduct their own survey research. As a group, students design a national sample survey and field the survey. Students analyze the survey results and examine literatures related to the content of the survey. Ideal for second and third year PhD students and advanced undergraduates, though others are welcome.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"E53-485"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.276"},{"code":"17.30","title":"Making Public Policy","level":"U","description":"Examines how the struggle among competing advocates shapes the outputs of government. Considers how conditions become problems for government to solve, why some political arguments are more persuasive than others, why some policy tools are preferred over others, and whether policies achieve their goals. Investigates the interactions among elected officials, think tanks, interest groups, the media, and the public in controversies over global warming, urban sprawl, Social Security, health care, education, and other issues.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"W41-1216"}]},{"type":"Recitation","options":[{"days":["R"],"start":"19:00","end":"20:00","room":"W41-1101"},{"days":["R"],"start":"20:00","end":"21:00","room":"W41-1101"},{"days":["F"],"start":"10:00","end":"11:00","room":"W41-1101"},{"days":["F"],"start":"11:00","end":"12:00","room":"W41-1101"},{"days":["F"],"start":"12:00","end":"13:00","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.30"},{"code":"17.303","title":"Methods of Policy Analysis","level":"U","description":"Provides students with an introduction to public policy analysis. Examines various approaches to policy analysis by considering the concepts, tools, and methods used in economics, political science, and other disciplines. Students apply and critique these approaches through case studies of current public policy problems.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"W41-1305"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.303"},{"code":"17.310","title":"Science, Technology, and Public Policy","level":"G","description":"Analysis of issues at the intersection of science, technology, public policy, and business. Cases drawn from antitrust and intellectual property rights; health and environmental policy; defense procurement and strategy; strategic trade and industrial policy; and R&D funding. Structured around theories of political economy, modified to take account of integration of uncertain technical information into public and private decision-making. Meets with 17.309 when offered concurrently.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.310"},{"code":"17.381","title":"Leadership in Negotiation: Advanced Applications","level":"U","description":"Building on the skills and strategies honed in 11.011, explores advanced negotiation practice. Emphasizes an experiential skill-building approach, underpinned by cutting-edge cases and innovative research. Examines applications in high-stakes management, public policy, social entrepreneurship, international diplomacy, and scientific discovery. Strengthens collaborative decision-making, persuasion, and leadership skills by negotiating across different media and through personalized coaching, enhancing students' ability to proactively engage stakeholders, transform organizations, and inspire communities. Limited by lottery; consult class website for information and deadlines.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"12:00","room":"W41-1306"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.381"},{"code":"17.391","title":"Human Rights at Home and Abroad","level":"U","description":"Provides a rigorous and critical introduction to the history, foundation, structure, and operation of the human rights movement. Focuses on key ideas, actors, methods and sources, and critically evaluates the field. Addresses current debates in human rights, including the relationship with security, democracy, development and globalization, urbanization, equality (in housing and other economic and social rights; women's rights; ethnic, religious and racial discrimination; and policing/conflict), post-conflict rebuilding and transitional justice, and technology in human rights activism. No prior coursework needed, but work experience, or community service that demonstrates familiarity with global affairs or engagement with ethics and social justice issues, preferred. Students taking graduate version are expected to write a research paper.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"W41-3101"}]}],"url":"http://student.mit.edu/catalog/m17a.html#17.391"},{"code":"17.407","title":"Chinese Foreign Policy","level":"U","description":"Explores the leading theoretical and methodological approaches to studying China's interaction with the world since 1949. Readings include books and articles that integrate the study of China's foreign policy with the field of international relations. Requires basic understanding of Chinese politics or international relations theory. Meets with 17.408 when offered concurrently.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.407"},{"code":"17.418","title":"Field Seminar in International Relations Theory","level":"G","description":"Provides an overview of the field of international relations. Each week a different approach to explaining international relations is examined. Surveys major concepts and theories in the field to assist in the preparation for further study in the department's other graduate offerings in international relations.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"09:00","end":"11:00","room":"E53-485"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.418"},{"code":"17.432","title":"Causes of War: Theory and Method","level":"G","description":"Provides an in-depth survey of scholarly theories associated with war. Examines when, where, and why wars—both interstate and intrastate—occur, why some conflicts escalate, and how wars end. Drawing from scholarship in political science and other disciplines, students explore debates over the variables that cause war and the mechanisms through which conflicts unfold. Includes readings that offer both theoretical and empirical insights.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"15:00","room":"E53-438"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.432"},{"code":"17.452","title":"Emerging Technology, Intelligence, and the Problem of Surprise","level":"G","description":"Examines the effect of emerging technologies on the organization and operation of intelligence agencies and how these technologies can and cannot address the steady-state challenges of interpretation, uncertainty, politicization, and surprise. Readings and case studies ground students in the work of leading intelligence scholars and, focusing on intelligence analysis, examine the effect of rational actor assumptions on intelligence failure. Designed for students interested in security studies, public policy, and emerging technologies.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"15:00","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.452"},{"code":"17.468","title":"Foundations of Security Studies","level":"G","description":"Develops a working knowledge of the theories and conceptual frameworks that form the intellectual basis of security studies as an academic discipline. Particular emphasis on balance of power theory, organization theory, civil-military relations, and the relationship between war and politics. The reading list includes Jervis, Schelling, Waltz, Blainey, von Clausewitz, and Huntington. Students write a seminar paper in which theoretical insights are systematically applied to a current security issue.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"10:00","end":"12:00","room":"E53-438"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.468"},{"code":"17.488","title":"Simulating Global Dynamics and War","level":"G","description":"Explores the history, tools, and utility of crisis simulations and war games that model international dynamics. Aims to develop toolkits for future worlds exercises and for the production of conference papers and peer-reviewed publications. Students review historical debates about gaming and simulation methods while gaining experience designing and playing different kinds of exercises, including technical operational games, computerized rapid play games, nuclear crisis games, and global dynamics simulations.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:00","end":"12:00","room":"E51-085"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.488"},{"code":"17.50","title":"Introduction to Comparative Politics","level":"U","description":"Examines why democracy emerges and survives in some countries rather than in others; how political institutions affect economic development; and how American politics compares to that of other countries. Reviews economic, cultural, and institutional explanations for political outcomes. Includes case studies of politics in several countries. Assignments include several papers of varying lengths and extensive structured and unstructured class participation. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:00","room":"66-160"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"14N-325"},{"days":["F"],"start":"11:00","end":"12:00","room":"14N-325"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.50"},{"code":"17.503","title":"How Dictatorship Works","level":"U","description":"Investigates the different nature of threats that dictators, kings, and autocrats face from the population who want democratization and other powerful elites who want to replace them. Considers the different ways dictatorial leaders institutionally design their regimes to temper these competing threats. These include coup-proofing their internal security apparatus, repressing the population, controlling the media, and co-opting rivals.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"66-144"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.503"},{"code":"17.526","title":"Comparative Urban Development","level":"G","description":"Examines both classic and recent research on urban politics, including studies of resource distribution, clientelism and machine politics, ethnic politics, property rights, economic informality, and violence in cities spanning the developing world, and also draws comparisons to urban areas in developed democracies. Special attention is paid to the effects of urban context on political behavior. Readings are primarily from political science, but also include work from sociology, economics, and related disciplines.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:00","end":"11:00","room":"E53-485"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.526"},{"code":"17.57","title":"20th Century Ukraine and Russia: Entangled Histories and Identity Politics","level":"U","description":"Explores the political and historical evolution of relations between Ukraine and Russia from 1900 to the present, with particular focus on the Soviet period from 1917 onward. Examines Ukrainian debates about autonomy and independence in the pre-revolutionary period; the revolutions of 1905 and 1917; the creation of the new Soviet state; the wars of 1917-1922; industrialization and collectivization, including the famines of 1932-1933; Stalinism; World War II; reform and stagnation; attempts at reform under Gorbachev; and, finally, the dramatic divergence of the two regions after 1991. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"14:30","room":"56-154"}]},{"type":"Recitation","options":[{"days":["R"],"start":"13:00","end":"14:30","room":"56-154"},{"days":["R"],"start":"13:00","end":"14:30","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.57"},{"code":"17.580","title":"Contentious Politics","level":"G","description":"Examines the causes and consequences of mobilized collective action broadly defined, including protests, social movements, riots, rebellions, and revolution ? instances of contentious politics that seek to promote societal or political change from outside formal political or state institutions. Does not focus on a particular region of the world but instead draws heavily from non-democratic settings and recent episodes of mobilization.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"E53-438"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.580"},{"code":"17.800","title":"Quantitative Research Methods I: Regression","level":"G","description":"Introduction to statistical research in political science and public policy, with a focus on linear regression. Teaches students how to apply multiple regression models as used in much of political science and public policy research. Also covers elements of probability and sampling theory. Limited to 30; preference to Course 17 PhD students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"E51-063"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.800"},{"code":"17.801","title":"Political Science Scope and Methods","level":"U","description":"Introduces principles of empirical and theoretical analysis in political science through research projects currently conducted in the department. Different department faculty lead modules that introduce students to major research questions and different ways of examining those questions. Emphasizes how this research in progress relates to larger themes, and how researchers confront obstacles to inference in political science. Includes substantial instruction and practice in writing (with revision) and oral presentations. Intended primarily for majors and minors.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"E51-390"}]},{"type":"Recitation","options":[{"days":["W"],"start":"15:00","end":"16:00","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.801"},{"code":"17.804","title":"Quantitative Research Methods III: Generalized Linear Models and Extensions","level":"G","description":"Provides a survey of statistical tools for model-based inference in political science and public policy. Topics include generalized linear models for various data types and their extensions, such as discrete choice models, survival outcome models, mixed effects and multilevel models. Covers both frequentist and Bayesian approaches. Limited to 15; preference to Course 17 PhD students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"E51-390"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.804"},{"code":"17.812","title":"Game Theory Toolkit for Political Science Research","level":"G","description":"Introduces core models and equilibrium concepts in normal-form and extensive-form games, under both complete and incomplete information. Blends lectures with paper discussions and guided problem solving. Assignments emphasize reading political science research, interpreting conclusions in light of assumptions, and formulating game theoretic models to capture empirical and conceptual findings. Culminates in a research project.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"E53-485"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.812"},{"code":"17.839","title":"Democracy and AI","level":"U","description":"Examines the political implications of AI through an academic lens. Analyzes how AI reshapes democratic participation, deliberation, and representation, while also considering its role in misinformation, surveillance, and authoritarian control. Focuses on regulatory frameworks, ethical principles, and the broader geopolitical competition over AI governance.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"2-151"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.839"},{"code":"17.850","title":"Political Science Scope and Methods","level":"G","description":"Introduces principles of empirical and theoretical analysis in political science. Exposes students to major research questions and different ways of examining them. Limited to Course 17 PhD students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"10:00","end":"12:00","room":"E53-438"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.850"},{"code":"17.90","title":"Politics, Policy, and Political Science: What Does It All Mean?","level":"U","description":"Explores the scope of political science, policy, and politics through conversations with faculty who research across the field. Topics include misinformation and democracy, dictatorships, nuclear war and AI, and why governments make the policy decisions they do. Gives a broad overview of the role of methods and data in political science. This class counts towards the 6-unit discovery-focused credit limit for first-year students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"16:30","room":"8-205"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.90"},{"code":"17.S952","title":"Special Graduate Subject in Political Science","level":"G","description":"Open to qualified graduate students who would like to pursue special subjects or projects. Please consult graduate administration prior to registration.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"E51-393"}]}],"url":"http://student.mit.edu/catalog/m17b.html#17.S952"},{"code":"18.0002","title":"Introduction to Computational Science and Engineering","level":"U","description":"Provides an introduction to computational algorithms used throughout engineering and science (natural and social) to simulate time-dependent phenomena; optimize and control systems; and quantify uncertainty in problems involving randomness, including an introduction to probability and statistics. Combination of 6.0001 and 16.0002 counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"33-419"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.0002"},{"code":"18.01","title":"Calculus","level":"U","description":"Differentiation and integration of functions of one variable, with applications. Informal treatment of limits and continuity. Differentiation: definition, rules, application to graphing, rates, approximations, and extremum problems. Indefinite integration; separable first-order differential equations. Definite integral; fundamental theorem of calculus. Applications of integration to geometry and science. Elementary functions. Techniques of integration. Polar coordinates. L'Hopital's rule. Improper integrals. Infinite series: geometric, p-harmonic, simple comparison tests, power series for some elementary functions.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-190"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"2-136"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"2-136"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"2-139"},{"days":["M","W"],"start":"12:00","end":"13:00","room":"2-139"},{"days":["M","W"],"start":"13:00","end":"14:00","room":"2-139"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.01"},{"code":"18.01A","title":"Calculus","level":"U","description":"Six-week review of one-variable calculus, emphasizing material not on the high-school AB syllabus: integration techniques and applications, improper integrals, infinite series, applications to other topics, such as probability and statistics, as time permits. Prerequisites: one year of high-school calculus or the equivalent, with a score of 5 on the AB Calculus test (or the AB portion of the BC test, or an equivalent score on a standard international exam), or equivalent college transfer credit, or a passing grade on the first half of the 18.01 advanced standing exam.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"2-142"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"2-142"},{"days":["M","W"],"start":"12:00","end":"13:00","room":"2-142"},{"days":["M","W"],"start":"13:00","end":"14:00","room":"2-142"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.01A"},{"code":"18.01L","title":"Calculus","level":"U","description":"Differentiation and integration of functions of one variable, with applications (see full description under 18.01). Material covered over a longer interval so that the subject is completed by the end of IAP. Emphasis given to ensuring foundational concepts are developed. Content, depth, and difficulty is otherwise identical to that of 18.01. The subject is designated as 18.01 on the transcript.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-132"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"13:00","end":"14:00","room":"2-147"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.01L"},{"code":"18.02","title":"Calculus","level":"U","description":"Calculus of several variables. Vector algebra in 3-space, determinants, matrices. Vector-valued functions of one variable, space motion. Scalar functions of several variables: partial differentiation, gradient, optimization techniques. Double integrals and line integrals in the plane; exact differentials and conservative fields; Green's theorem and applications, triple integrals, line and surface integrals in space, Divergence theorem, Stokes' theorem; applications.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"26-100"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"09:00","end":"10:00","room":"2-135"},{"days":["M","W"],"start":"10:00","end":"11:00","room":"2-135"},{"days":["M","W"],"start":"10:00","end":"11:00","room":"26-210"},{"days":["M","W"],"start":"10:00","end":"11:00","room":"1-135"},{"days":["M","W"],"start":"10:00","end":"11:00","room":"2-147"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"2-135"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"26-210"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"1-135"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"2-147"},{"days":["M","W"],"start":"12:00","end":"13:00","room":"2-135"},{"days":["M","W"],"start":"12:00","end":"13:00","room":"26-210"},{"days":["M","W"],"start":"12:00","end":"13:00","room":"1-135"},{"days":["M","W"],"start":"13:00","end":"14:00","room":"2-135"},{"days":["M","W"],"start":"13:00","end":"14:00","room":"26-210"},{"days":["M","W"],"start":"13:00","end":"14:00","room":"1-135"},{"days":["M","W"],"start":"14:00","end":"15:00","room":"2-135"},{"days":["M","W"],"start":"15:00","end":"16:00","room":"2-135"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.02"},{"code":"18.022","title":"Calculus","level":"U","description":"Calculus of several variables. Topics as in 18.02 but with more focus on mathematical concepts. Vector algebra, dot product, matrices, determinant. Functions of several variables, continuity, differentiability, derivative. Parametrized curves, arc length, curvature, torsion. Vector fields, gradient, curl, divergence. Multiple integrals, change of variables, line integrals, surface integrals. Stokes' theorem in one, two, and three dimensions.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"35-225"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"13:00","end":"14:00","room":"4-145"},{"days":["M","W"],"start":"14:00","end":"15:00","room":"4-145"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.022"},{"code":"18.02A","title":"Calculus","level":"U","description":"First half is taught during the last six weeks of the Fall term; covers material in the first half of 18.02 (through double integrals). Second half of 18.02A can be taken either during IAP (daily lectures) or during the second half of the Spring term; it covers the remaining material in 18.02.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"2-142"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"2-142"},{"days":["M","W"],"start":"12:00","end":"13:00","room":"2-142"},{"days":["M","W"],"start":"13:00","end":"14:00","room":"2-142"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.02A"},{"code":"18.03","title":"Differential Equations","level":"U","description":"Study of differential equations, including modeling physical systems. Solution of first-order ODEs by analytical, graphical, and numerical methods. Linear ODEs with constant coefficients. Complex numbers and exponentials. Inhomogeneous equations: polynomial, sinusoidal, and exponential inputs. Oscillations, damping, resonance. Fourier series. Matrices, eigenvalues, eigenvectors, diagonalization. First order linear systems: normal modes, matrix exponentials, variation of parameters. Heat equation, wave equation. Nonlinear autonomous systems: critical point analysis, phase plane diagrams.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"26-100"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"09:00","end":"10:00","room":"2-135"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"2-135"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"2-143"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"2-135"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"2-143"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"2-135"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"2-143"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"2-135"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"2-143"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"2-135"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.03"},{"code":"18.062","title":"Mathematics for Computer Science","level":"U","description":"Elementary discrete mathematics for science and engineering, with a focus on mathematical tools and proof techniques useful in computer science. Topics include logical notation, sets, relations, elementary graph theory, state machines and invariants, induction and proofs by contradiction, recurrences, asymptotic notation, elementary analysis of algorithms, elementary number theory and cryptography, permutations and combinations, counting tools, and discrete probability.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"26-100"}]},{"type":"Recitation","options":[{"days":["W","F"],"start":"10:00","end":"11:00","room":"26-168"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"38-166"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"36-153"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"26-168"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"38-166"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"24-307"},{"days":["W","F"],"start":"15:00","end":"16:00","room":"26-168"},{"days":["W","F"],"start":"15:00","end":"16:00","room":"38-166"},{"days":["W","F"],"start":"15:00","end":"16:00","room":"26-204"},{"days":["W","F"],"start":"16:00","end":"17:00","room":"26-168"},{"days":["W","F"],"start":"10:00","end":"11:00","room":"36-144"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"26-168"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"36-144"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"13-3101"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"26-168"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"36-144"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"13-3101"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"26-168"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.062"},{"code":"18.085","title":"Computational Science and Engineering I","level":"U","description":"Review of linear algebra, applications to networks, structures, and estimation, finite difference and finite element solution of differential equations, Laplace's equation and potential flow, boundary-value problems, Fourier series, discrete Fourier transform, convolution. Frequent use of MATLAB in a wide range of scientific and engineering applications.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"6-120"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.085"},{"code":"18.0851","title":"Computational Science and Engineering I","level":"G","description":"Review of linear algebra, applications to networks, structures, and estimation, finite difference and finite element solution of differential equations, Laplace's equation and potential flow, boundary-value problems, Fourier series, discrete Fourier transform, convolution. Frequent use of MATLAB in a wide range of scientific and engineering applications. Students in Course 18 must register for the undergraduate version, 18.085.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"6-120"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.0851"},{"code":"18.090","title":"Introduction to Mathematical Reasoning","level":"U","description":"Focuses on understanding and constructing mathematical arguments. Discusses foundational topics (such as infinite sets, quantifiers, and methods of proof) as well as selected concepts from algebra (permutations, vector spaces, fields) and analysis (sequences of real numbers). Particularly suitable for students desiring additional experience with proofs before going on to more advanced mathematics subjects or subjects in related areas with significant mathematical content.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"2-136"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.090"},{"code":"18.1001","title":"Real Analysis","level":"G","description":"Covers fundamentals of mathematical analysis: convergence of sequences and series, continuity, differentiability, Riemann integral, sequences and series of functions, uniformity, interchange of limit operations. Shows the utility of abstract concepts and teaches understanding and construction of proofs. Proofs and definitions are less abstract than in 18.100B. Gives applications where possible. Concerned primarily with the real line. Students in Course 18 must register for undergraduate version 18.100A.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.1001"},{"code":"18.1002","title":"Real Analysis","level":"G","description":"Covers fundamentals of mathematical analysis: convergence of sequences and series, continuity, differentiability, Riemann integral, sequences and series of functions, uniformity, interchange of limit operations. Shows the utility of abstract concepts and teaches understanding and construction of proofs. More demanding than 18.100A, for students with more mathematical maturity. Places more emphasis on point-set topology and n-space. Students in Course 18 must register for undergraduate version 18.100B.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.1002"},{"code":"18.100A","title":"Real Analysis","level":"U","description":"Covers fundamentals of mathematical analysis: convergence of sequences and series, continuity, differentiability, Riemann integral, sequences and series of functions, uniformity, interchange of limit operations. Shows the utility of abstract concepts and teaches understanding and construction of proofs. Proofs and definitions are less abstract than in 18.100B. Gives applications where possible. Concerned primarily with the real line.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.100A"},{"code":"18.100B","title":"Real Analysis","level":"U","description":"Covers fundamentals of mathematical analysis: convergence of sequences and series, continuity, differentiability, Riemann integral, sequences and series of functions, uniformity, interchange of limit operations. Shows the utility of abstract concepts and teaches understanding and construction of proofs. More demanding than 18.100A, for students with more mathematical maturity. Places more emphasis on point-set topology and n-space.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.100B"},{"code":"18.104","title":"Seminar in Analysis","level":"U","description":"Students present and discuss material from books or journals. Topics vary from year to year. Instruction and practice in written and oral communication provided. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"2-151"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.104"},{"code":"18.112","title":"Functions of a Complex Variable","level":"U","description":"Studies the basic properties of analytic functions of one complex variable. Conformal mappings and the Poincare model of non-Euclidean geometry. Cauchy-Goursat theorem and Cauchy integral formula. Taylor and Laurent decompositions. Singularities, residues and computation of integrals. Harmonic functions and Dirichlet's problem for the Laplace equation. The partial fractions decomposition. Infinite series and infinite product expansions. The Gamma function. The Riemann mapping theorem. Elliptic functions.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"4-370"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.112"},{"code":"18.1121","title":"Functions of a Complex Variable","level":"G","description":"Studies the basic properties of analytic functions of one complex variable. Conformal mappings and the Poincare model of non-Euclidean geometry. Cauchy-Goursat theorem and Cauchy integral formula. Taylor and Laurent decompositions. Singularities, residues and computation of integrals. Harmonic functions and Dirichlet's problem for the Laplace equation. The partial fractions decomposition. Infinite series and infinite product expansions. The Gamma function. The Riemann mapping theorem. Elliptic functions. Students in Course 18 must register for the undergraduate version, 18.112.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"4-370"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.1121"},{"code":"18.155","title":"Differential Analysis I","level":"G","description":"First part of a two-subject sequence. Review of Lebesgue integration. Lp spaces. Distributions. Fourier transform. Sobolev spaces. Spectral theorem, discrete and continuous spectrum. Homogeneous distributions. Fundamental solutions for elliptic, hyperbolic and parabolic differential operators. Recommended prerequisite: 18.112.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"2-136"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.155"},{"code":"18.175","title":"Theory of Probability","level":"G","description":"Sums of independent random variables, central limit  phenomena, infinitely divisible laws, Levy processes,  Brownian motion, conditioning, and martingales.  Prior exposure to probability (e.g., 18.600) recommended.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.175"},{"code":"18.177","title":"Topics in Stochastic Processes","level":"G","description":"","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"2-131"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.177"},{"code":"18.204","title":"Undergraduate Seminar in Discrete Mathematics","level":"U","description":"Seminar in combinatorics, graph theory, and discrete mathematics in general. Participants read and present papers from recent mathematics literature. Instruction and practice in written and oral communication provided. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-257"},{"days":["T","R"],"start":"11:00","end":"12:30","room":"1-134"},{"days":["T","R"],"start":"11:00","end":"12:30","room":"56-162"},{"days":["T","R"],"start":"11:00","end":"12:30","room":"2-142"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.204"},{"code":"18.211","title":"Combinatorial Analysis","level":"U","description":"Combinatorial problems and methods for their solution. Enumeration, generating functions, recurrence relations, construction of bijections. Introduction to graph theory. Prior experience with abstraction and proofs is helpful.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"2-190"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.211"},{"code":"18.217","title":"Combinatorial Theory","level":"G","description":"Content varies from year to year.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"32-141"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.217"},{"code":"18.305","title":"Advanced Analytic Methods in Science and Engineering","level":"G","description":"Covers expansion around singular points: the WKB method on ordinary and partial differential equations; the method of stationary phase and the saddle point method; the two-scale method and the method of renormalized perturbation; singular perturbation and boundary-layer techniques; WKB method on partial differential equations.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"4-370"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.305"},{"code":"18.335","title":"Introduction to Numerical Methods","level":"G","description":"Advanced introduction to numerical analysis: accuracy and efficiency of numerical algorithms. In-depth coverage of sparse-matrix/iterative and dense-matrix algorithms in numerical linear algebra (for linear systems and eigenproblems). Floating-point arithmetic, backwards error analysis, conditioning, and stability. Other computational topics (e.g., numerical integration or nonlinear optimization) may also be surveyed. Final project involves some programming.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.335"},{"code":"18.353","title":"Nonlinear Dynamics: Chaos","level":"U","description":"Introduction to nonlinear dynamics and chaos in dissipative systems. Forced and parametric oscillators. Phase space. Periodic, quasiperiodic, and aperiodic flows. Sensitivity to initial conditions and strange attractors. Lorenz attractor. Period doubling, intermittency, and quasiperiodicity. Scaling and universality. Analysis of experimental data: Fourier transforms, Poincare sections, fractal dimension, and Lyapunov exponents. Applications to mechanical systems, fluid dynamics, physics, geophysics, and chemistry. See 12.207J/18.354J for Nonlinear Dynamics: Continuum Systems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"2-361"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.353"},{"code":"18.385","title":"Nonlinear Dynamics and Chaos","level":"G","description":"Introduction to the theory of nonlinear dynamical systems with applications from science and engineering. Local and global existence of solutions, dependence on initial data and parameters. Elementary bifurcations, normal forms. Phase plane, limit cycles, relaxation oscillations, Poincare-Bendixson theory. Floquet theory. Poincare maps. Averaging. Near-equilibrium dynamics. Synchronization. Introduction to chaos. Universality. Strange attractors. Lorenz and Rossler systems. Hamiltonian dynamics and KAM theory. Uses MATLAB computing environment.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"3-333"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.385"},{"code":"18.404","title":"Theory of Computation","level":"U","description":"A more extensive and theoretical treatment of the material in 6.1400J/18.400J, emphasizing computability and computational complexity theory. Regular and context-free languages. Decidable and undecidable problems, reducibility, recursive function theory. Time and space measures on computation, completeness, hierarchy theorems, inherently complex problems, oracles, probabilistic computation, and interactive proof systems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"54-100"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"4-159"},{"days":["F"],"start":"11:00","end":"12:00","room":"4-159"},{"days":["F"],"start":"12:00","end":"13:00","room":"4-257"},{"days":["F"],"start":"13:00","end":"14:00","room":"4-257"},{"days":["F"],"start":"14:00","end":"15:00","room":"4-145"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.404"},{"code":"18.4041","title":"Theory of Computation","level":"G","description":"A more extensive and theoretical treatment of the material in 6.1400J/18.400J, emphasizing computability and computational complexity theory. Regular and context-free languages. Decidable and undecidable problems, reducibility, recursive function theory. Time and space measures on computation, completeness, hierarchy theorems, inherently complex problems, oracles, probabilistic computation, and interactive proof systems. Students in Course 18 must register for the undergraduate version, 18.404.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"54-100"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"4-159"},{"days":["F"],"start":"11:00","end":"12:00","room":"4-159"},{"days":["F"],"start":"12:00","end":"13:00","room":"4-257"},{"days":["F"],"start":"13:00","end":"14:00","room":"4-257"},{"days":["F"],"start":"14:00","end":"15:00","room":"4-145"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.4041"},{"code":"18.410","title":"Design and Analysis of Algorithms","level":"U","description":"Techniques for the design and analysis of efficient algorithms, emphasizing methods useful in practice. Topics include sorting; search trees, heaps, and hashing; divide-and-conquer; dynamic programming; greedy algorithms; amortized analysis; graph algorithms; and shortest paths. Advanced topics may include network flow; computational geometry; number-theoretic algorithms; polynomial and matrix calculations; caching; and parallel computing.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"34-101"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"36-155"},{"days":["F"],"start":"13:00","end":"14:00","room":"26-210"},{"days":["F"],"start":"13:00","end":"14:00","room":"36-156"},{"days":["F"],"start":"15:00","end":"16:00","room":"34-301"},{"days":["F"],"start":"09:00","end":"10:00","room":"34-301"},{"days":["F"],"start":"14:00","end":"15:00","room":"36-153"},{"days":["F"],"start":"14:00","end":"15:00","room":"36-112"},{"days":["F"],"start":"15:00","end":"16:00","room":"36-153"},{"days":["F"],"start":"10:00","end":"11:00","room":"36-156"},{"days":["F"],"start":"11:00","end":"12:00","room":"36-155"},{"days":["F"],"start":"11:00","end":"12:00","room":"36-156"},{"days":["F"],"start":"12:00","end":"13:00","room":"26-210"},{"days":["F"],"start":"12:00","end":"13:00","room":"36-156"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.410"},{"code":"18.415","title":"Advanced Algorithms","level":"G","description":"First-year graduate subject in algorithms. Emphasizes fundamental algorithms and advanced methods of algorithmic design, analysis, and implementation. Surveys a variety of computational models and the algorithms for them. Data structures, network flows, linear programming, computational geometry, approximation algorithms, online algorithms, parallel algorithms, external memory, streaming algorithms.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:30","end":"16:00","room":"32-123"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.415"},{"code":"18.424","title":"Seminar in Information Theory","level":"U","description":"Considers various topics in information theory, including data compression, Shannon's Theorems, and error-correcting codes. Students present and discuss the subject matter. Instruction and practice in written and oral communication provided. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"2-131"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.424"},{"code":"18.425","title":"Foundations of Cryptography","level":"G","description":"A rigorous introduction to modern cryptography. Emphasis on the fundamental cryptographic primitives such as public-key encryption, digital signatures, and pseudo-random number generation, as well as advanced cryptographic primitives such as zero-knowledge proofs, homomorphic encryption, and secure multiparty computation.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"2-190"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.425"},{"code":"18.435","title":"Quantum Computation","level":"G","description":"Provides an introduction to the theory and practice of quantum computation. Topics covered: physics of information processing; quantum algorithms including the factoring algorithm and Grover's search algorithm; quantum error correction; quantum communication and cryptography. Knowledge of quantum mechanics helpful but not required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"54-100"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.435"},{"code":"18.438","title":"Quantum Information Science III","level":"G","description":"Third subject in the Quantum Information Science (QIS) sequence, building on 8.370 and 8.371. Further explores core topics in quantum information science, such as quantum information theory, error-correction, physical implementations, algorithms, cryptography, and complexity. Draws connections between QIS and related fields, such as many-body physics, and applications such as sensing.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"2-136"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.438"},{"code":"18.600","title":"Probability and Random Variables","level":"U","description":"Probability spaces, random variables, distribution functions. Binomial, geometric, hypergeometric, Poisson distributions. Uniform, exponential, normal, gamma and beta distributions. Conditional probability, Bayes theorem, joint distributions. Chebyshev inequality, law of large numbers, and central limit theorem. Credit cannot also be received for 6.041A or 6.041B.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"34-101"}]},{"type":"Recitation","options":[{"days":["R"],"start":"10:00","end":"11:00","room":"5-233"},{"days":["R"],"start":"11:00","end":"12:00","room":"5-233"},{"days":["R"],"start":"12:00","end":"13:00","room":"5-233"},{"days":["R"],"start":"13:00","end":"14:00","room":"5-233"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.600"},{"code":"18.604","title":"Seminar In Probability Theory","level":"U","description":"Students work on group presentations on topics selected by students from a provided list of suggestions. Topics may include Benford's law, random walks and electrical networks, and Brownian motions. Assignments include three group presentations, two individual presentations, and a final individual term paper. Instruction in oral and written communication provided to effectively communicate about probability theory. Limited to 16.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"2-147"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.604"},{"code":"18.615","title":"Introduction to Stochastic Processes","level":"G","description":"Basics of stochastic processes. Markov chains, Poisson processes, random walks, birth and death processes, Brownian motion.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-370"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.615"},{"code":"18.642","title":"Topics in Mathematics with Applications in Finance","level":"U","description":"Introduction to mathematical concepts and techniques used in finance. Lectures focusing on linear algebra, probability, statistics, stochastic processes, and numerical methods are interspersed with lectures by financial sector professionals illustrating the corresponding application in the industry. Prior knowledge of economics or finance helpful but not required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.642"},{"code":"18.650","title":"Fundamentals of Statistics","level":"U","description":"A rapid introduction to the theoretical foundations of statistical methods that are useful in many applications. Covers a broad range of topics in a short amount of time with the goal of providing a rigorous and cohesive understanding of the modern statistical landscape. Mathematical language is used for intuition and basic derivations but not proofs. Main topics include: parametric estimation, confidence intervals, hypothesis testing, Bayesian inference, and linear and logistic regression. Additional topics may include: causal inference, nonparametric estimation, and classification.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["R"],"start":"11:00","end":"12:00","room":"4-149"},{"days":["R"],"start":"12:00","end":"13:00","room":"4-149"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.650"},{"code":"18.6501","title":"Fundamentals of Statistics","level":"G","description":"A rapid introduction to the theoretical foundations of statistical methods that are useful in many applications. Covers a broad range of topics in a short amount of time with the goal of providing a rigorous and cohesive understanding of the modern statistical landscape. Mathematical language is used for intuition and basic derivations but not proofs. Main topics include: parametric estimation, confidence intervals, hypothesis testing, Bayesian inference, and linear and logistic regression. Additional topics may include: causal inference, nonparametric estimation, and classification. Students in Course 18 must register for the undergraduate version, 18.650.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["R"],"start":"11:00","end":"12:00","room":"4-149"},{"days":["R"],"start":"12:00","end":"13:00","room":"4-149"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.6501"},{"code":"18.657","title":"Topics in Statistics","level":"G","description":"Not offered academic year 2027-2028","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"2-131"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.657"},{"code":"18.675","title":"Theory of Probability","level":"G","description":"Sums of independent random variables, central limit phenomena, infinitely divisible laws, Levy processes, Brownian motion, conditioning, and martingales. Prior exposure to probability (e.g., 18.600) recommended.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.675"},{"code":"18.700","title":"Linear Algebra","level":"U","description":"Vector spaces, systems of linear equations, bases, linear independence, matrices, determinants, eigenvalues, inner products, quadratic forms, and canonical forms of matrices. More emphasis on theory and proofs than in 18.06.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.700"},{"code":"18.701","title":"Algebra I","level":"U","description":"18.701-18.702 is more extensive and theoretical than the 18.700-18.703 sequence. Experience with proofs necessary. 18.701 focuses on group theory, geometry, and linear algebra.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"34-101"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.701"},{"code":"18.704","title":"Seminar in Algebra","level":"U","description":"Topics vary from year to year. Students present and discuss the subject matter. Instruction and practice in written and oral communication provided. Some experience with proofs required. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"2-151"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.704"},{"code":"18.705","title":"Commutative Algebra","level":"G","description":"Exactness, direct limits, tensor products, Cayley-Hamilton theorem, integral dependence, localization, Cohen-Seidenberg theory, Noether normalization, Nullstellensatz, chain conditions, primary decomposition, length, Hilbert functions, dimension theory, completion, Dedekind domains.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"2-131"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.705"},{"code":"18.725","title":"Algebraic Geometry I","level":"G","description":"Introduces the basic notions and techniques of modern algebraic geometry. Covers fundamental notions and results about algebraic varieties over an algebraically closed field; relations between complex algebraic varieties and complex analytic varieties; and examples with emphasis on algebraic curves and surfaces. Introduction to the language of schemes and properties of morphisms. Knowledge of elementary algebraic topology, elementary differential geometry recommended, but not required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"2-147"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.725"},{"code":"18.745","title":"Lie Groups and Lie Algebras I","level":"G","description":"Covers fundamentals of the theory of Lie algebras and related groups. Topics may include theorems of Engel and Lie; enveloping algebra, Poincare-Birkhoff-Witt theorem; classification and construction of semisimple Lie algebras; the center of their enveloping algebras; elements of representation theory; compact Lie groups and/or finite Chevalley groups.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"2-146"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.745"},{"code":"18.785","title":"Number Theory I","level":"G","description":"Dedekind domains, unique factorization of ideals, splitting of primes. Lattice methods, finiteness of the class group, Dirichlet's unit theorem. Local fields, ramification, discriminants. Zeta and L-functions, analytic class number formula. Adeles and ideles. Statements of class field theory and the Chebotarev density theorem.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"2-136"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.785"},{"code":"18.821","title":"Project Laboratory in Mathematics","level":"U","description":"Guided research in mathematics, employing the scientific method. Students confront puzzling and complex mathematical situations, through the acquisition of data by computer, pencil and paper, or physical experimentation, and attempt to explain them mathematically. Students choose three projects from a large collection of options. Each project results in a laboratory report subject to revision; oral presentation on one or two projects. Projects drawn from many areas, including dynamical systems, number theory, algebra, fluid mechanics, asymptotic analysis, knot theory, and probability. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"11:00","room":"2-146"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.821"},{"code":"18.901","title":"Introduction to Topology","level":"U","description":"Introduces topology, covering topics fundamental to modern analysis and geometry. Topological spaces and continuous functions, connectedness, compactness, separation axioms, covering spaces, and the fundamental group.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"37-212"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.901"},{"code":"18.9011","title":"Introduction to Topology","level":"G","description":"Introduces topology, covering topics fundamental to modern analysis and geometry. Topological spaces and continuous functions, connectedness, compactness, separation axioms, covering spaces, and the fundamental group. Students in Course 18 must register for the undergraduate version, 18.901.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"37-212"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.9011"},{"code":"18.916","title":"Geometric Methods in Algebraic Topology","level":"G","description":"Continues the development of algebraic topology, with a focus on methods from differential and geometric topology. Topics include characteristic classes, cobordism, and K-theory. Usually, only one of 18.906 or 18.916 is offered in a given academic year.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"26-210"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.916"},{"code":"18.950","title":"Differential Geometry","level":"U","description":"Introduction to differential geometry, centered on notions of curvature. Starts with curves in the plane, and proceeds to higher dimensional submanifolds. Computations in coordinate charts: first and second fundamental form, Christoffel symbols. Discusses the distinction between extrinsic and intrinsic aspects, in particular Gauss' theorema egregium. The Gauss-Bonnet theorem. Geodesics. Examples such as hyperbolic space.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.950"},{"code":"18.9501","title":"Differential Geometry","level":"G","description":"Introduction to differential geometry, centered on notions of curvature. Starts with curves in the plane, and proceeds to higher dimensional submanifolds. Computations in coordinate charts: first and second fundamental form, Christoffel symbols. Discusses the distinction between extrinsic and intrinsic aspects, in particular Gauss' theorema egregium. The Gauss-Bonnet theorem. Geodesics. Examples such as hyperbolic space. Students in Course 18 must register for the undergraduate version, 18.950.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.9501"},{"code":"18.C06","title":"Linear Algebra and Optimization","level":"U","description":"Introductory course in linear algebra and optimization, assuming no prior exposure to linear algebra and starting from the basics, including vectors, matrices, eigenvalues, singular values, and least squares. Covers the basics in optimization including convex optimization, linear/quadratic programming, gradient descent, and regularization, building on insights from linear algebra. Explores a variety of applications in science and engineering, where the tools developed give powerful ways to understand complex systems and also extract structure from data.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"45-230"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"10:00","end":"11:00","room":"45-102"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"45-102"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"45-102"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m18a.html#18.C06"},{"code":"18.C20","title":"Introduction to Computational Science and Engineering","level":"U","description":"Provides an introduction to computational algorithms used throughout engineering and science (natural and social) to simulate time-dependent phenomena; optimize and control systems; and quantify uncertainty in problems involving randomness, including an introduction to probability and statistics. Combination of 6.100A and 16.C20J counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"3-370"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.C20"},{"code":"18.C25","title":"Real World Computation with Julia","level":"U","description":"Focuses on algorithms and techniques for writing and using modern technical software in a job, lab, or research group environment that may consist of interdisciplinary teams, where performance may be critical, and where the software needs to be flexible and adaptable. Topics include automatic differentiation, matrix calculus, scientific machine learning, parallel and GPU computing, and performance optimization with introductory applications to climate science, economics, agent-based modeling, and other areas. Labs and projects focus on performant, readable, composable algorithms, and software. Programming will be in Julia. Expects students to have some familiarity with Python, Matlab, or R. No Julia experience necessary.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.C25"},{"code":"18.S995","title":"Special Subject in Mathematics","level":"G","description":"Opportunity for group study of advanced subjects in mathematics not otherwise included in the curriculum. Offerings are initiated by members of the mathematics faculty on an ad hoc basis, subject to departmental approval.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m18b.html#18.S995"},{"code":"2.00","title":"Introduction to Design","level":"U","description":"Project-based introduction to product development and engineering design. Emphasizes key elements of the design process, including defining design problems, generating ideas, and building solutions. Presents a range of design techniques to help students think about, evaluate, and communicate designs, from sketching to physical prototyping, as well as other types of modeling. Students work both individually and in teams.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"16:00","end":"17:00","room":"1-390"}]},{"type":"Lab","options":[{"days":["R"],"start":"09:30","end":"12:30","room":"1-307"},{"days":["R"],"start":"14:00","end":"17:00","room":"1-307"},{"days":["F"],"start":"12:30","end":"15:30","room":"1-307"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.00"},{"code":"2.001","title":"Mechanics and Materials I","level":"U","description":"Introduction to statics and the mechanics of deformable solids. Emphasis on the three basic principles of equilibrium, geometric compatibility, and material behavior. Stress and its relation to force and moment; strain and its relation to displacement; linear elasticity with thermal expansion. Failure modes. Application to simple engineering structures such as rods, shafts, beams, and trusses.  Application to biomechanics of natural materials and structures.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"3-270"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:30","end":"15:00","room":"1-307"},{"days":["R"],"start":"09:30","end":"11:00","room":"1-307"},{"days":["R"],"start":"11:00","end":"12:30","room":"1-307"},{"days":["R"],"start":"12:30","end":"14:00","room":"1-307"},{"days":["R"],"start":"14:00","end":"15:30","room":"1-307"},{"days":["R"],"start":"15:30","end":"17:00","room":"1-307"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.001"},{"code":"2.003","title":"Dynamics and Control I","level":"U","description":"Introduction to the dynamics and vibrations of lumped-parameter models of mechanical systems. Kinematics. Force-momentum formulation for systems of particles and rigid bodies in planar motion. Work-energy concepts.  Virtual displacements and virtual work. Lagrange's equations for systems of particles and rigid bodies in planar motion. Linearization of equations of motion. Linear stability analysis of mechanical systems. Free and forced vibration of linear multi-degree of freedom models of mechanical systems; matrix eigenvalue problems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"10-250"}]},{"type":"Recitation","options":[{"days":["R"],"start":"12:00","end":"13:00","room":"1-371"},{"days":["R"],"start":"13:00","end":"14:00","room":"3-442"},{"days":["R"],"start":"14:00","end":"15:00","room":"3-442"},{"days":["F"],"start":"10:00","end":"11:00","room":"5-217"},{"days":["F"],"start":"11:00","end":"12:00","room":"5-217"},{"days":["F"],"start":"12:00","end":"13:00","room":"5-233"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.003"},{"code":"2.004","title":"Dynamics and Control II","level":"U","description":"Modeling, analysis, and control of dynamic systems. System modeling: lumped parameter models of mechanical, electrical, and electromechanical systems; interconnection laws; actuators and sensors. Linear systems theory: linear algebra; Laplace transform; transfer functions, time response and frequency response, poles and zeros; block diagrams; solutions via analytical and numerical techniques; stability. Introduction to feedback control: closed-loop response; PID compensation; steady-state characteristics, root-locus design concepts, frequency-domain design concepts. Laboratory experiments and control design projects. Enrollment may be limited due to laboratory capacity; preference to Course 2 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"3-270"}]},{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"15:00","room":"3-062B"},{"days":["M"],"start":"15:00","end":"17:00","room":"3-062B"},{"days":["T"],"start":"13:00","end":"15:00","room":"3-062B"},{"days":["T"],"start":"15:00","end":"17:00","room":"3-062B"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"4-270"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.004"},{"code":"2.005","title":"Thermal-Fluids Engineering I","level":"U","description":"Integrated development of the fundamental principles of thermodynamics, fluid mechanics, and heat transfer, with applications. Focuses on the first and second laws of thermodynamics, mass conservation, and momentum conservation, for both closed and open systems. Entropy generation and its influence on the performance of engineering systems. Introduction to dimensionless numbers. Introduction to heat transfer: conduction, convection, and radiation. Steady-state and transient conduction. Finned surfaces. The heat equation and the lumped capacitance model. Coupled and uncoupled fluid models. Hydrostatics. Inviscid flow analysis and Bernoulli equation. Navier-Stokes equation and its solutions. Viscous internal flows, head losses, and turbulence. Introduction to pipe flows and Moody chart.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:00","end":"11:00","room":"1-190"}]},{"type":"Recitation","options":[{"days":["R"],"start":"14:00","end":"15:00","room":"1-246"},{"days":["R"],"start":"15:00","end":"16:00","room":"1-246"},{"days":["R"],"start":"16:00","end":"17:00","room":"1-246"},{"days":["F"],"start":"10:00","end":"11:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.005"},{"code":"2.006","title":"Thermal-Fluids Engineering II","level":"U","description":"Focuses on the application of the principles of thermodynamics, heat transfer, and fluid mechanics to the design and analysis of engineering systems. Dimensional analysis, similarity, and modeling. Pipe systems: major and minor losses. Laminar and turbulent boundary layers. Boundary layer separation, lift and drag on objects. Heat transfer associated with laminar and turbulent flow of fluids in free and forced convection in channels and over surfaces. Pure substance model. Heat transfer in boiling and condensation. Thermodynamics and fluid mechanics of steady flow components of thermodynamic plants. Heat exchanger design. Power cycles and refrigeration plants. Design of thermodynamic plants. Analyses for alternative energy systems. Multi-mode heat transfer and fluid flow in thermodynamic plants.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"3-370"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-371"},{"days":["F"],"start":"14:00","end":"15:00","room":"1-371"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.006"},{"code":"2.008","title":"Design and Manufacturing II","level":"U","description":"Integration of design, engineering, and management disciplines and practices for analysis and design of manufacturing enterprises. Emphasis is on the physics and stochastic nature of manufacturing processes and systems, and their effects on quality, rate, cost, and flexibility. Topics include process physics and control, design for manufacturing, and manufacturing systems. Group project requires design and fabrication of parts using mass-production and assembly methods to produce a product in quantity. Six units may be applied to the General Institute Lab Requirement. Satisfies 6 units of Institute Laboratory credit. Enrollment may be limited due to laboratory capacity; preference to Course 2 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"35-225"}]},{"type":"Lab","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"35-125"},{"days":["T"],"start":"09:00","end":"12:00","room":"35-125"},{"days":["T"],"start":"14:00","end":"17:00","room":"35-125"},{"days":["W"],"start":"09:00","end":"12:00","room":"35-125"},{"days":["R"],"start":"09:00","end":"12:00","room":"35-125"},{"days":["R"],"start":"14:00","end":"17:00","room":"35-125"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.008"},{"code":"2.009","title":"The Product Engineering Process","level":"U","description":"Students develop an understanding of product development phases and experience working in teams to design and construct high-quality product prototypes. Design process learned is placed into a broader development context. Primary goals are to improve ability to reason about design alternatives and apply modeling techniques appropriate for different development phases; understand how to gather and process customer information and transform it into engineering specifications; and use teamwork to resolve the challenges in designing and building a substantive product prototype. Instruction and practice in oral communication provided. Enrollment may be limited due to laboratory capacity; preference to Course 2 seniors.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"10-250"}]},{"type":"Lab","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"3-037A"},{"days":["M"],"start":"14:00","end":"17:00","room":"3-037C"},{"days":["T"],"start":"09:00","end":"12:00","room":"3-037A"},{"days":["T"],"start":"14:00","end":"17:00","room":"3-037A"},{"days":["T"],"start":"14:00","end":"17:00","room":"3-037C"},{"days":["W"],"start":"14:00","end":"17:00","room":"3-037A"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.009"},{"code":"2.013","title":"Engineering Systems Design","level":"U","description":"Focuses on the design of engineering systems to satisfy stated performance, stability, and/or control requirements. Emphasizes individual initiative, application of fundamental principles, and the compromises inherent in the engineering design process. Culminates in the design of an engineering system, typically a vehicle or other complex system. Includes instruction and practice in written and oral communication through team presentations, design reviews, and written reports. Students taking graduate version complete additional assignments. Enrollment may be limited due to laboratory capacity; preference to Course 2 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"17:00","room":"NE45-202A"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.013"},{"code":"2.016","title":"Hydrodynamics","level":"U","description":"Covers fundamental principles of fluid mechanics and applications to practical ocean engineering problems. Basic geophysical fluid mechanics, including the effects of salinity, temperature, and density; heat balance in the ocean; large scale flows. Hydrostatics. Linear free surface waves, wave forces on floating and submerged structures. Added mass, lift and drag forces on submerged bodies. Includes final project on current research topics in marine hydrodynamics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"3-442"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.016"},{"code":"2.032","title":"Dynamics","level":"G","description":"Review of momentum principles. Hamilton's principle and Lagrange's equations. Three-dimensional kinematics and dynamics of rigid bodies. Study of steady motions and small deviations therefrom, gyroscopic effects, causes of instability. Free and forced vibrations of lumped-parameter and continuous systems. Nonlinear oscillations and the phase plane. Nonholonomic systems. Introduction to wave propagation in continuous systems.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"1-150"}]},{"type":"Recitation","options":[{"days":["T"],"start":"16:00","end":"17:00","room":"1-371"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.032"},{"code":"2.036","title":"Nonlinear Dynamics and Chaos","level":"G","description":"Introduction to the theory of nonlinear dynamical systems with applications from science and engineering. Local and global existence of solutions, dependence on initial data and parameters. Elementary bifurcations, normal forms. Phase plane, limit cycles, relaxation oscillations, Poincare-Bendixson theory. Floquet theory. Poincare maps. Averaging. Near-equilibrium dynamics. Synchronization. Introduction to chaos. Universality. Strange attractors. Lorenz and Rossler systems. Hamiltonian dynamics and KAM theory. Uses MATLAB computing environment.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"3-333"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.036"},{"code":"2.050","title":"Nonlinear Dynamics: Chaos","level":"U","description":"Introduction to nonlinear dynamics and chaos in dissipative systems. Forced and parametric oscillators. Phase space. Periodic, quasiperiodic, and aperiodic flows. Sensitivity to initial conditions and strange attractors. Lorenz attractor. Period doubling, intermittency, and quasiperiodicity. Scaling and universality. Analysis of experimental data: Fourier transforms, Poincare sections, fractal dimension, and Lyapunov exponents. Applications to mechanical systems, fluid dynamics, physics, geophysics, and chemistry. See 12.207J/18.354J for Nonlinear Dynamics: Continuum Systems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"2-361"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.050"},{"code":"2.060","title":"Structural Dynamics","level":"G","description":"Examines response of structures to dynamic excitation: free vibration, harmonic loads, pulses and earthquakes. Covers systems of single- and multiple-degree-of-freedom, up to the continuum limit, by exact and approximate methods. Includes applications to buildings, ships, aircraft and offshore structures. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.060"},{"code":"2.073","title":"Solid Mechanics: Plasticity and Inelastic Deformation","level":"G","description":"Physical basis of plastic/inelastic deformation of solids; metals, polymers, granular/rock-like materials. Continuum constitutive models for small and large deformation of elastic-(visco)plastic solids. Analytical and numerical solution of selected boundary value problems. Applications to deformation processing of metals.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.073"},{"code":"2.074","title":"Solid Mechanics: Elasticity","level":"G","description":"Introduction to the theory and applications of nonlinear and linear elasticity. Strain, stress, and stress-strain relations. Several of the following topics: Spherically and cylindrically symmetric problems. Anisotropic material behavior. Piezoelectric materials. Effective properties of composites. Structural mechanics of beams and plates. Energy methods for structures. Two-dimensional problems. Stress concentration at cavities, concentrated loads, cracks, and dislocations. Variational methods and their applications; introduction to the finite element method. Introduction to wave propagation.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"1-246"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"3-333"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.074"},{"code":"2.075","title":"Mechanics of Soft Materials","level":"G","description":"Covers a number of fundamental topics in the emerging field of soft and active materials, including polymer mechanics and physics, poroelasticity, viscoelasticity, and mechanics of electro-magneto-active and other responsive polymers. Lectures, recitations, and experiments elucidate the basic mechanical and thermodynamic principles underlying soft and active materials. Develops an understanding of the fundamental mechanisms for designing soft materials that possess extraordinary properties, such as stretchable, tough, strong, resilient, adhesive and responsive to external stimuli, from molecular to bulk scales.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"5-234"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.075"},{"code":"2.080","title":"Structural Mechanics","level":"G","description":"Applies solid mechanics fundamentals to the analysis of marine, civil, and mechanical structures.  Continuum concepts of stress, deformation, constitutive response and boundary conditions are reviewed in selected examples. The principle of virtual work guides mechanics modeling of slender structural components (e.g., beams; shafts; cables, frames; plates; shells), leading to appropriate simplifying assumptions. Introduction to elastic stability.  Material limits to stress in design. Variational methods for computational structural mechanics analysis.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"2-105"}]},{"type":"Recitation","options":[{"days":["F"],"start":"09:00","end":"10:00","room":"5-217"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.080"},{"code":"2.083","title":"Topology Optimization of Structures","level":"G","description":"Covers free-form topology design of structures using formal optimization methods and mathematical programs, including design of structural systems, mechanisms, and material architectures. Strong emphasis on designing with gradient-based optimizers, finite element methods, and design problems governed by structural mechanics. Incorporates optimization theory and computational mechanics fundamentals, problem formulation, sensitivity analysis; and introduces cutting-edge extensions, including to other and multiple physics.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"1-273"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.083"},{"code":"2.086","title":"Numerical Computation for Mechanical Engineers","level":"U","description":"Covers elementary programming concepts, including variable types, data structures, and flow control. Provides an introduction to linear algebra and probability. Numerical methods relevant to MechE, including approximation (interpolation, least squares, and statistical regression), integration, solution of linear and nonlinear equations, and ordinary differential equations. Presents deterministic and probabilistic approaches. Uses examples from MechE, particularly from robotics, dynamics, and structural analysis. Assignments require MATLAB programming. Enrollment may be limited due to laboratory capacity; preference to Course 2 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:00","end":"13:00","room":"3-270"}]},{"type":"Lab","options":[{"days":["W"],"start":"14:30","end":"16:30","room":"3-442"},{"days":["R"],"start":"09:00","end":"11:00","room":"5-134"},{"days":["R"],"start":"14:30","end":"16:30","room":"5-234"},{"days":["F"],"start":"09:00","end":"11:00","room":"3-442"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.086"},{"code":"2.0911","title":"Computational Design and Fabrication","level":"U","description":"Introduces computational aspects of computer-aided design and manufacturing. Explores relevant methods in the context of additive manufacturing (e.g., 3D printing). Topics include computer graphics (geometry modeling, solid modeling, procedural modeling), physically-based simulation (kinematics, finite element method), 3D scanning/geometry processing, and an overview of 3D fabrication methods. Exposes students to the latest research in computational fabrication. Students taking the graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"32-141"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.0911"},{"code":"2.094","title":"Atomistic Modeling and Simulation of Materials and Structures","level":"G","description":"Covers multiscale atomistic modeling and simulation methods, with focus on mechanical properties (elasticity, plasticity, creep, fracture, fatigue) of a range of materials (metals, ceramics, proteins, biological materials, biomaterials). Topics include mechanics of materials (energy principles, nano-/micromechanics, deformation mechanisms, size effects, hierarchical biological structures) and atomistic modeling (chemistry, interatomic potentials, chemical reactivity and first-principles methods, visualization, data analysis, numerical methods, supercomputing, data-driven algorithms). Includes interactive computational projects and cloud-based computing. Part I – Basic atomistic and multiscale methods, Part II – Interatomic potentials, Part III – Mechanical properties at multiple scales, Part IV – Materiomics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"3-333"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.094"},{"code":"2.096","title":"Introduction to Modeling and Simulation","level":"G","description":"Introduction to computational techniques for modeling and simulation of a variety of large and complex engineering, science, and socio-economical systems. Prepares students for practical use and development of computational engineering in their own research and future work. Topics include mathematical formulations (e.g., automatic assembly of constitutive and conservation principles); linear system solvers (sparse and iterative); nonlinear solvers (Newton and homotopy); ordinary, time-periodic and partial differential equation solvers; and model order reduction. Students develop their own models and simulators for self-proposed applications, with an emphasis on creativity, teamwork, and communication. Prior basic linear algebra required and at least one numerical programming language (e.g., MATLAB, Julia, Python, etc.) helpful.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.096"},{"code":"2.097","title":"Numerical Methods for Partial Differential Equations","level":"G","description":"Covers the fundamentals of modern numerical techniques for a wide range of linear and nonlinear elliptic, parabolic, and hyperbolic partial differential and integral equations. Topics include mathematical formulations; finite difference, finite volume, finite element, and boundary element discretization methods; and direct and iterative solution techniques. The methodologies described form the foundation for computational approaches to engineering systems involving heat transfer, solid mechanics, fluid dynamics, and electromagnetics. Computer assignments requiring programming.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"37-212"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.097"},{"code":"2.111","title":"Quantum Computation","level":"G","description":"Provides an introduction to the theory and practice of quantum computation. Topics covered: physics of information processing; quantum algorithms including the factoring algorithm and Grover's search algorithm; quantum error correction; quantum communication and cryptography. Knowledge of quantum mechanics helpful but not required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"54-100"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.111"},{"code":"2.132","title":"Instrumentation and Measurement: MICA Projects","level":"U","description":"Engages students in project-based learning by using a wide variety of experimental setups called MICA (Measurement, Instrumentation, Control, and Analysis) Workstations to learn about sensors, actuators, instrumentation, and measurement techniques. Over 50 MICA Workstations allow experiments to be performed on a broad range of phenomena including those found in optics, electronics, acoustics, biology, botany, material science, mechanics, thermal, and fluid systems. Experiments utilize Mathematica Notebooks in which students conduct data analysis and model fitting, and complete homework assignments. The integration of ChatGPT into Mathematica provides help in the learning process. Students also build new Workstations guided by CAD models and develop the Mathematica code to run experiments, perform data analyses, and model parameter estimation. Students taking graduate version build more sophisticated Workstations..","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"3-149"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.132"},{"code":"2.133","title":"Instrumentation and Measurement: MICA Projects","level":"G","description":"Engages students in project-based learning by using a wide variety of experimental setups called MICA (Measurement, Instrumentation, Control, and Analysis) Workstations to learn about sensors, actuators, instrumentation, and measurement techniques. Over 50 MICA Workstations allow experiments to be performed on a broad range of phenomena including those found in optics, electronics, acoustics, biology, botany, material science, mechanics, thermal, and fluid systems. Experiments utilize Mathematica Notebooks in which students conduct data analysis and model fitting, and complete homework assignments. The integration of ChatGPT into Mathematica provides help in the learning process. Students also build new Workstations guided by CAD models and develop the Mathematica code to run experiments, perform data analyses, and model parameter estimation. Students taking graduate version build more sophisticated Workstations.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"3-149"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.133"},{"code":"2.145","title":"Design of Compliant Mechanisms, Machines and Systems","level":"U","description":"Design, modeling and integration of compliance into systems that enable performance which is impractical to obtain via rigid mechanisms. Includes multiple strategies (pseudo-rigid body, topology synthesis, freedom and constraint topology) to engineer compliant mechanisms for mechanical systems. Emphasis is placed upon the integration of first principles (math/physics/engineering classes) to optimize kinematics, stiffness, energy storage/release, load capacity, efficiency and integration with actuation/sensing. Synthesize concepts, optimize them via computational models and test prototypes. Prototypes integrate multiple engineering sub-disciplines (e.g. mechanics + dynamics or mechanics + energy) and are drawn from biological systems, prosthetics, energy harvesting, precision instrumentation, robotics, space-based systems and others. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"35-310"}]},{"type":"Lab","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"4-149"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.145"},{"code":"2.147","title":"Design of Compliant Mechanisms, Machines and Systems","level":"G","description":"Design, modeling and integration of compliance into systems that enable performance which is impractical to obtain via rigid mechanisms. Students learn strategies (pseudo-rigid body, topology synthesis, freedom and constraint topology) to engineer compliant mechanisms for mechanical systems. Emphasis is placed upon the integration of first principles (math/physics/engineering classes) to optimize kinematics, stiffness, energy storage/release, load capacity, efficiency and integration with actuation/sensing. Students synthesize concepts, optimize them via computational models and test prototypes. Prototypes integrate multiple engineering sub-disciplines (e.g. mechanics + dynamics or mechanics + energy) and are drawn from biological systems, prosthetics, energy harvesting, precision instrumentation, robotics, space-based systems and others. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"35-310"}]},{"type":"Lab","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"4-149"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.147"},{"code":"2.151","title":"Advanced System Dynamics and Control","level":"G","description":"Analytical descriptions of state-determined dynamic physical systems; time and frequency domain representations; system characteristics - controllability, observability, stability; linear and nonlinear system responses. Modification of system characteristics using feedback. State observers, Kalman filters. Modeling/performance trade-offs in control system design. Basic optimization tools. Positive systems. Emphasizes applications to physical systems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"3-370"}]},{"type":"Recitation","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"3-442"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.151"},{"code":"2.154","title":"Maneuvering and Control of Surface  and Underwater Vehicles","level":"G","description":"Maneuvering motions of surface and underwater vehicles. Derivation of equations of motion, hydrodynamic coefficients. Memory effects. Linear and nonlinear forms of the equations of motion. Control surfaces modeling and design. Engine, propulsor, and transmission systems modeling and simulation during maneuvering. Stability of motion. Principles of multivariable automatic control. Optimal control, Kalman filtering, loop transfer recovery. Term project: applications chosen from autopilots for surface vehicles; towing in open seas; remotely operated vehicles.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"5-217"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.154"},{"code":"2.155","title":"Artificial Intelligence and Machine Learning for Engineering Design","level":"U","description":"Machine learning and artificial intelligence techniques in engineering design applications. Emphasizes state-of-the-art machine learning techniques to design new products or systems or solve complex engineering problems. Lectures cover the theoretical and practical aspects of machine learning and optimization methods. Challenge problems, research paper discussions, and interactive in-class activities are used to highlight the unique challenges of machine learning for design applications. A group term project on students' applications of interest. Basic programming and machine learning familiarity are recommended. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.155"},{"code":"2.156","title":"Artificial Intelligence and Machine Learning for Engineering Design","level":"G","description":"Machine learning and artificial intelligence techniques in engineering design applications. Emphasizes state-of-the-art machine learning techniques to design new products or systems or solve complex engineering problems. Lectures cover the theoretical and practical aspects of machine learning and optimization methods. Challenge problems, research paper discussions, and interactive in-class activities are used to highlight the unique challenges of machine learning for design applications. A group term project on students' applications of interest. Basic programming and machine learning familiarity are recommended. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.156"},{"code":"2.160","title":"Identification, Estimation, and Learning","level":"G","description":"Provides a broad theoretical basis for estimation, identification, and learning of linear and nonlinear systems at the cross-disciplinary area of system dynamics and control, machine learning, and statistics. Recursive least squares estimate, partial least squares, Kalman filter and extended Kalman filter, Bayes filter and particle filter; parametric and non-parametric system identification, Wiener-Hopf equation, persistent excitation, unbiased estimates, asymptotic variance, experiment design; function approximation theory, neural nets, radial basis functions, Koopman operator for exact linearization of nonlinear systems, and dynamic mode decomposition. Context-oriented mini-projects: robotics, self-driving cars, biomedical engineering, wearable sensors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"5-234"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.160"},{"code":"2.165","title":"Robotics","level":"G","description":"Introduction to robotics and learning in machines. Kinematics and dynamics of rigid body systems. Adaptive control, system identification, sparse representations. Force control, adaptive visual servoing. Task planning, teleoperation, imitation learning. Navigation. Underactuated systems, approximate optimization and control. Dynamics of learning and optimization in networks. Elements of biological planning and control. Motor primitives, entrainment, active sensing, binding models. Term projects.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"5-217"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.165"},{"code":"2.177","title":"Designing Virtual Worlds","level":"U","description":"Three primary areas of focus are: creating new Virtual Reality experiences; mapping the state of emerging tools; and hosting guests ? leaders in the VR/XR community, who serve as coaches for projects. Students have significant leeway to customize their own learning environment. As the field is rapidly evolving, each semester focuses on a new aspect of virtual worlds, based on the current state of innovations. Students work in teams of interdisciplinary peers from Berklee College of Music and Harvard University. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:30","end":"16:30","room":"3-370"}]},{"type":"Recitation","options":[{"days":["T"],"start":"19:00","end":"20:00","room":"9-152"},{"days":["W"],"start":"19:00","end":"20:00","room":"9-152"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.177"},{"code":"2.178","title":"Designing Virtual Worlds","level":"G","description":"Three primary areas of focus are: creating new Virtual Reality experiences; mapping the state of emerging tools; and hosting guests ? leaders in the VR/XR community, who serve as coaches for projects. Students have significant leeway to customize their own learning environment. As the field is rapidly evolving, each semester focuses on a new aspect of virtual worlds, based on the current state of innovations. Students work in teams of interdisciplinary peers from Berklee College of Music and Harvard University. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:30","end":"16:30","room":"3-370"}]},{"type":"Recitation","options":[{"days":["T"],"start":"19:00","end":"20:00","room":"9-152"},{"days":["W"],"start":"19:00","end":"20:00","room":"9-152"}]}],"url":"http://student.mit.edu/catalog/m2a.html#2.178"},{"code":"2.20","title":"Marine Hydrodynamics","level":"G","description":"The fundamentals of fluid mechanics are developed in the context of naval architecture and ocean science and engineering. Transport theorem and conservation principles. Navier-Stokes' equation. Dimensional analysis. Ideal and potential flows. Vorticity and Kelvin's theorem. Hydrodynamic forces in potential flow, D'Alembert's paradox, added-mass, slender-body theory. Viscous-fluid flow, laminar and turbulent boundary layers. Model testing, scaling laws. Application of potential theory to surface waves, energy transport, wave/body forces. Linearized theory of lifting surfaces. Experimental project in the towing tank or propeller tunnel.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"5-134"}]},{"type":"Recitation","options":[{"days":["W"],"start":"11:00","end":"12:00","room":"1-132"},{"days":["W"],"start":"13:00","end":"14:00","room":"1-371"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.20"},{"code":"2.25","title":"Fluid Mechanics","level":"G","description":"Survey of principal concepts and methods of fluid dynamics. Mass conservation, momentum, and energy equations for continua. Navier-Stokes equation for viscous flows. Similarity and dimensional analysis. Lubrication theory. Boundary layers and separation. Circulation and vorticity theorems. Potential flow. Introduction to turbulence. Lift and drag. Surface tension and surface tension driven flows.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"3-370"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:00","end":"14:30","room":"5-217"},{"days":["W"],"start":"15:30","end":"17:00","room":"5-233"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.25"},{"code":"2.28","title":"Fundamentals and Applications of Combustion","level":"G","description":"Fundamentals and modeling of reacting gas dynamics and combustion using analytical and numerical methods. Conservation equations of reacting flows. Multi-species transport, chemical thermodynamics and chemical kinetics. Non-equilibrium flow. Detonation and reacting boundary layers. Ignition, flammability, and extinction. Premixed and diffusion flames. Combustion instabilities. Supersonic combustion. Turbulent combustion. Liquid and solid burning. Fire, safety, and environmental impact. Applications to power and propulsion.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.28"},{"code":"2.42","title":"General Thermodynamics","level":"G","description":"General foundations of thermodynamics from an entropy point of view, entropy generation and transfer in complex systems. Definitions of work, energy, stable equilibrium, available energy, entropy, thermodynamic potential, and interactions other than work (nonwork, heat, mass transfer). Applications to properties of materials, bulk flow, energy conversion, chemical equilibrium, combustion, and industrial manufacturing.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"1-277"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.42"},{"code":"2.611","title":"Marine Power and Propulsion","level":"G","description":"Selection and evaluation of commercial and naval ship power and propulsion systems. Analysis of propulsors, prime mover thermodynamic cycles, propeller-engine matching. Propeller selection, waterjet analysis, review of alternative propulsors; thermodynamic analyses of Rankine, Brayton, Diesel, and Combined cycles, reduction gears and integrated electric drive. Battery operated vehicles, fuel cells. Term project requires analysis of alternatives in propulsion plant design for given physical, performance, and economic constraints. Graduate students complete different assignments and exams.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"5-217"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"1-242"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.611"},{"code":"2.612","title":"Marine Power and Propulsion","level":"U","description":"Selection and evaluation of commercial and naval ship power and propulsion systems. Analysis of propulsors, prime mover thermodynamic cycles, propeller-engine matching. Propeller selection, waterjet analysis, review of alternative propulsors; thermodynamic analyses of Rankine, Brayton, Diesel, and Combined cycles, reduction gears and integrated  electric drive. Battery operated vehicles, fuel cells. Term project requires analysis of alternatives in propulsion plant design for given physical, performance, and economic constraints. Graduate students complete different assignments  and exams.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"5-217"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"1-242"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.612"},{"code":"2.625","title":"Electrochemical Energy Conversion and Storage: Fundamentals, Materials and Applications","level":"G","description":"Fundamental concepts, tools, and applications in electrochemical science and engineering. Introduces thermodynamics, kinetics and transport of electrochemical reactions. Describes how materials structure and properties affect electrochemical behavior of particular applications, for instance in lithium rechargeable batteries, electrochemical capacitors, fuel cells, photo electrochemical cells, and electrolytic cells. Discusses state-of-the-art electrochemical energy technologies for portable electronic devices, hybrid and plug-in vehicles, electrical vehicles. Theoretical and experimental exploration of electrochemical measurement techniques in cell testing, and in bulk and interfacial transport measurements (electronic and ionic resistivity and charge transfer cross the electrode-electrolyte interface).","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"3-333"}]},{"type":"Recitation","options":[{"days":["W"],"start":"16:00","end":"17:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.625"},{"code":"2.65","title":"Sustainable Energy","level":"G","description":"Assessment of current and potential future energy systems. Covers resources, extraction, conversion, and end-use technologies, with emphasis on meeting 21st-century regional and global energy needs in a sustainable manner. Examines various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal) energy types, along with storage, transmission, and conservation issues. Emphasizes analysis of energy propositions within an engineering, economic and social context. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.65"},{"code":"2.650","title":"Introduction to Sustainable Energy","level":"U","description":"Assessment of current and potential future energy systems. Covers resources, extraction, conversion, and end-use technologies, with emphasis on meeting 21st-century regional and global energy needs in a sustainable manner. Examines various renewable and conventional energy production technologies, energy end-use practices and alternatives, and consumption practices in different countries. Investigates their attributes within a quantitative analytical framework for evaluation of energy technology system proposals. Emphasizes analysis of energy propositions within an engineering, economic and social context. Students taking graduate version complete additional assignments. Limited to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.650"},{"code":"2.652","title":"Applications of Energy in Global Development","level":"U","description":"Engages students in project-based learning, in collaboration with D-Lab community partners, to improve access to affordable, reliable, sustainable, and modern energy for all. Teams work on off-grid energy projects addressing challenges in lighting, cooking, agricultural productivity, or other areas in collaboration with D-Lab community partners in developing countries. Project work includes assessment of user needs, technology identification, product design, prototyping, and development of implementation strategies to continue progress of ongoing projects. Optional IAP field visits may be available to test and implement the solutions developed during the semester. Students enrolled in the graduate version complete additional assignments.  Limited to 20; preference to students who have taken EC.711.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"15:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.652"},{"code":"2.671","title":"Measurement and Instrumentation","level":"U","description":"Introduces fundamental concepts and experimental techniques for observation and measurement of physical variables such as force and motion, liquid and gas properties, physiological parameters, and measurements of light, sound, electrical quantities, and temperature. Emphasizes mathematical techniques including uncertainty analysis and statistics, Fourier analysis, frequency response, and correlation functions. Uses engineering knowledge to select instruments and design experimental methods to obtain and interpret meaningful data. Guided learning during lab experiments promotes independent experiment design and measurements performed outside the lab in the semester-long 'Go Forth and Measure' project. Advances students' ability to critically read, evaluate, and extract specific technical meaning from information in a variety of media, and provides extensive instruction and practice in written, graphical, and oral communication. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:00","room":"3-270"}]},{"type":"Lab","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"3-038"},{"days":["T"],"start":"09:00","end":"12:00","room":"3-038"},{"days":["T"],"start":"14:00","end":"17:00","room":"3-038"},{"days":["W"],"start":"09:00","end":"12:00","room":"3-038"},{"days":["W"],"start":"14:00","end":"17:00","room":"3-038"},{"days":["R"],"start":"14:00","end":"17:00","room":"3-038"},{"days":["F"],"start":"09:00","end":"12:00","room":"3-038"},{"days":["F"],"start":"14:00","end":"17:00","room":"3-038"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.671"},{"code":"2.673","title":"Instrumentation and Measurement for Biological Systems","level":"U","description":"Explores the intricate relationship between measuring, manipulating, and modeling biological systems. Lectures cover the application of engineering techniques — such as statistics, signal processing, system identification, and control theory — to biological systems. Lab sessions focus on optical methods and electronics. Fundamental topics include measurement error and the limits of precision and accuracy. Students taking graduate version complete additional assignments. Enrollment limited; preference to Course 20 undergraduates.","groups":[{"type":"Lecture","options":[{"days":["T","R","F"],"start":"12:00","end":"13:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.673"},{"code":"2.675","title":"Micro/Nano Engineering Laboratory","level":"G","description":"Covers advanced nanoengineering via practical lab modules in connection with classical fluid dynamics, mechanics, thermodynamics, and material physics. Labs include microfluidic systems, microelectromechanical systems (MEMS), emerging nanomaterials such as graphene, carbon nanotubes (CNTs), and nanoimaging tools. Student teams lead an experimental term project that uses the tools and knowledge acquired through the lab modules and experimental work, and culminates in a report and presentation. Recitations cover idea development, experiment design, planning and execution, and analysis of results pertinent to the project. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"15:00","room":"1-246"}]},{"type":"Lab","options":[{"days":["R"],"start":"09:00","end":"12:00","room":"5-026"},{"days":["R"],"start":"13:00","end":"16:00","room":"5-026"},{"days":["F"],"start":"09:00","end":"12:00","room":"5-026"},{"days":["F"],"start":"13:00","end":"16:00","room":"5-026"}]},{"type":"Recitation","options":[{"days":["T"],"start":"13:00","end":"14:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.675"},{"code":"2.676","title":"Micro/Nano Engineering Laboratory","level":"U","description":"Studies advanced nanoengineering via experiental lab modules with classical fluid dynamics, mechanics, thermodynamics, and materials science. Lab modules include microfluidic systems; microelectromechanical systems (MEMS); emerging nanomaterials, such as graphene and carbon nanotubes (CNTs); and nanoimaging tools. Recitation develops in-depth knowledge and understanding of physical phenomena observed in the lab through quantitative analysis. Students have the option to engage in term projects led by students taking 2.675. Enrollment limited; preference to Course 2 and 2-OE majors and minors.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"15:00","room":"1-246"}]},{"type":"Lab","options":[{"days":["R"],"start":"09:00","end":"12:00","room":"5-026"},{"days":["R"],"start":"13:00","end":"16:00","room":"5-026"},{"days":["F"],"start":"09:00","end":"12:00","room":"5-026"},{"days":["F"],"start":"13:00","end":"16:00","room":"5-026"}]},{"type":"Recitation","options":[{"days":["T"],"start":"15:00","end":"16:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.676"},{"code":"2.678","title":"Electronics for Mechanical Systems","level":"U","description":"Practical introduction to the fundamentals of electronics in the context of electro-mechanical systems, with emphasis on experimentation and project work in basic electronics. Laboratory exercises include the design and construction of simple electronic devices, such as power supplies, amplifiers, op-amp circuits, switched mode dc-dc converters, and dc motor drivers. Surveys embedded microcontrollers as system elements. Laboratory sessions stress the understanding of electronic circuits at the component level, but also point out the modern approach of system integration using commercial modules and specialized integrated circuits. Enrollment may be limited due to laboratory capacity; preference to Course 2 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:00","room":"3-270"}]},{"type":"Lab","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"3-062B"},{"days":["R"],"start":"12:30","end":"14:30","room":"3-062B"},{"days":["R"],"start":"15:00","end":"17:00","room":"3-062B"},{"days":["F"],"start":"11:00","end":"13:00","room":"3-062B"},{"days":["F"],"start":"14:00","end":"16:00","room":"3-062B"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.678"},{"code":"2.681","title":"Environmental Ocean Acoustics","level":"G","description":"Covers the basic elements of ocean acoustic-wave propagation and scattering apropos of the particular physical, biological, geological, and chemical conditions found in ocean margins and basins, including high latitudes. Introduction provides an overview of ocean acoustics, especially remote sensing, navigation, and communication applications; analytical tools; and acoustically significant properties of seawater, including the equation of state. Treats the following topics: acoustic wave equation from the fundamental principles of fluid dynamics; properties of sound waves; acoustical environment of the ocean; plane-wave reflection and transmission at the sea surface and seabed; geometrical acoustics/ray theory; normal-mode theory; parabolic equation techniques; scattering from rough surfaces; bubbles; and numerical methods to solve the wave equation for scattering.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"16:00","end":"17:30","room":"54-823"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.681"},{"code":"2.688","title":"Principles of Oceanographic Instrument Systems -- Sensors and Measurements","level":"G","description":"Introduces theoretical and practical principles of design of oceanographic sensor systems. Transducer characteristics for acoustic, current, temperature, pressure, electric, magnetic, gravity, salinity, velocity, heat flow, and optical devices. Limitations on these devices imposed by ocean environment. Signal conditioning and recording; noise, sensitivity, and sampling limitations; standards. Principles of state-of-the-art systems being used in physical oceanography, geophysics, submersibles, acoustics discussed in lectures by experts in these areas.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"WHOI CAMPUS"}]},{"type":"Lab","options":[{"days":["T"],"start":"13:00","end":"16:00","room":"WHOI CAMPUS"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.688"},{"code":"2.70","title":"FUNdaMENTALS of Precision Product Design","level":"U","description":"Examines design, selection, and combination of machine elements to produce a robust precision system. Introduces process, philosophy and physics-based principles of design to improve/enable renewable power generation, energy efficiency, and manufacturing productivity. Topics include linkages, power transmission, screws and gears, actuators, structures, joints, bearings, error apportionment, and error budgeting. Considers each topic with respect to its physics of operation, mechanics (strength, deformation, thermal effects) and accuracy, repeatability, and resolution. Includes guest lectures from practicing industry and academic leaders.  Students design, build, and test a small benchtop precision machine, such as a heliostat for positioning solar PV panels or a two or three axis machine.  Prior to each lecture, students review the pre-recorded detailed topic materials and then converge on what parts of the topic they want covered in extra depth in lecture.  Students are assessed on their preparation for and participation in class sessions. Students taking graduate version complete additional assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"3-442"}]},{"type":"Lab","options":[{"days":["T"],"start":"12:30","end":"15:30","room":"3-442"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.70"},{"code":"2.700","title":"Principles of Naval Architecture","level":"U","description":"Presents principles of naval architecture, ship geometry, hydrostatics, calculation and drawing of curves of form, intact and damage stability, hull structure strength calculations and ship resistance. Introduces computer-aided naval ship design and analysis tools. Projects include analysis of ship lines drawings, calculation of ship hydrostatic characteristics, analysis of intact and damaged stability, ship model testing, and hull structure strength calculations. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"5-217"}]},{"type":"Lab","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.700"},{"code":"2.701","title":"Principles of Naval Architecture","level":"G","description":"Presents principles of naval architecture, ship geometry, hydrostatics, calculation and drawing of curves of form, intact and damage stability, hull structure strength calculations and ship resistance. Introduces computer-aided naval ship design and analysis tools. Projects include analysis of ship lines drawings, calculation of ship hydrostatic characteristics, analysis of intact and damaged stability, ship model testing, and hull structure strength calculations. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"5-217"}]},{"type":"Lab","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.701"},{"code":"2.703","title":"Principles of Naval Ship Design","level":"G","description":"Covers the design of surface ship platforms for naval applications. Includes topics such as hull form selection and concept design synthesis, topside and general arrangements, weight estimation, and technical feasibility analyses (including strength, stability, seakeeping, and survivability.). Practical exercises involve application of design principles and utilization of advanced computer-aided ship design tools.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"1-134"}]},{"type":"Recitation","options":[{"days":["W"],"start":"15:00","end":"16:00","room":"5-217"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.703"},{"code":"2.71","title":"Optics","level":"U","description":"Introduction to optical science with elementary engineering applications. Geometrical optics: ray-tracing, aberrations, lens design, apertures and stops, radiometry and photometry. Wave optics: basic electrodynamics, polarization, interference, wave-guiding, Fresnel and Fraunhofer diffraction, image formation, resolution, space-bandwidth product. Emphasis on analytical and numerical tools used in optical design. Graduate students are required to complete additional assignments with stronger analytical content, and an advanced design project.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.71"},{"code":"2.710","title":"Optics","level":"G","description":"Introduction to optical science with elementary engineering applications. Geometrical optics: ray-tracing, aberrations, lens design, apertures and stops, radiometry and photometry. Wave optics: basic electrodynamics, polarization, interference, wave-guiding, Fresnel and Fraunhofer diffraction, image formation, resolution, space-bandwidth product. Emphasis on analytical and numerical tools used in optical design. Graduate students are required to complete additional assignments with stronger analytical content, and an advanced design project.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.710"},{"code":"2.723","title":"Design Thinking and Innovation Leadership for Engineers","level":"U","description":"Project-based course develops students' ability to conceive, implement, and evaluate successful projects in any engineering discipline. Lessons focus on an iterative design process, techniques for leading the creative process in teams, the ethics of engineering systems, methods for articulating designs with group collaboration, identifying and reconciling paradoxes of engineering designs, using a systems thinking approach for stakeholder analysis, and communicating solution concepts with impact. Working in teams, students employ design thinking techniques and leadership skills to collaboratively conceive, implement, and iteratively refine through user feedback robust applications using a simple web-based platform. Students also give oral presentations and receive feedback to sharpen their communication skills.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"VIRTUAL"}]},{"type":"Design","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"VIRTUAL"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.723"},{"code":"2.7231","title":"Introduction to Design Thinking and Innovation in Engineering","level":"U","description":"Introduces students to concepts of design thinking and innovation that can be applied to any engineering discipline. Focuses on introducing an iterative design process, a systems-thinking approach for stakeholder analysis, methods for articulating design concepts, methods for concept selection, and techniques for testing with users. Provides an opportunity for first-year students to explore product or system design and development, and to build their understanding of what it means to lead and coordinate projects in engineering design. Subject can count toward the 6-unit discovery-focused credit limit for first-year students. Enrollment limited to 25; priority to first-year students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"32-123"},{"days":["W"],"start":"12:00","end":"13:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.7231"},{"code":"2.723A","title":"Design Thinking and Innovation Leadership for Engineers","level":"U","description":"Introductory subject in design thinking and innovation. Develops students' ability to conceive, implement, and evaluate successful projects in any engineering discipline. Lessons focus on an iterative design process, a systems-thinking approach for stakeholder analysis, methods for articulating design concepts, methods for concept selection, and techniques for testing with users.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"32-141"},{"days":["M"],"start":"15:00","end":"17:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"32-123"},{"days":["W"],"start":"12:00","end":"13:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m2b.html#2.723A"}]);
